import type { AuditEventRecord } from "./audit-history";
import { formatPlanningRowsText } from "../planning-lifecycle/row-summary";

export type AuditFieldTone = "normal" | "muted" | "changed";
export type AuditServiceFieldKey =
  | "dateTime"
  | "language"
  | "priest"
  | "organist"
  | "antiphon"
  | "topic"
  | "note"
  | "rows"
  | "lifecycle";

export type AuditServiceField = {
  key: AuditServiceFieldKey;
  text: string;
  tone: AuditFieldTone;
};

export type AuditStatePresentation =
  | { kind: "empty" }
  | { kind: "service"; fields: AuditServiceField[] }
  | { kind: "generic"; text: string };

export type AuditEventPresentation = {
  objectLabel: string;
  action: string;
  actorLabel: string;
  occurredAtLabel: string;
  before: AuditStatePresentation;
  after: AuditStatePresentation;
};

type LifecycleLabel = "Working Plan" | "Final Plan" | "Completed Service";

type ServiceSnapshot = {
  dateTime: string;
  dateTimeComparable: string;
  language: string;
  priest: string;
  priestComparable: string;
  organist: string;
  organistComparable: string;
  antiphonPresent: boolean;
  antiphonComparable: string;
  topicPresent: boolean;
  topicComparable: string;
  notePresent: boolean;
  noteComparable: string;
  rowsText: string;
  rowsComparable: string;
  lifecycle: LifecycleLabel;
};

export function presentAuditEvent(event: AuditEventRecord): AuditEventPresentation {
  const isPlanningEvent = event.action.startsWith("planning.");
  let beforeSnapshot = extractServiceSnapshot(event.beforeState);
  const afterSnapshot = extractServiceSnapshot(event.afterState);

  if (
    !beforeSnapshot
    && afterSnapshot
    && (event.action === "planning.final.autoComplete" || event.action === "planning.final.complete")
  ) {
    beforeSnapshot = { ...afterSnapshot, lifecycle: "Final Plan" };
  }

  return {
    objectLabel: `Object ${event.objectRef}:`,
    action: event.action,
    actorLabel: event.actorKind === "system"
      ? "System"
      : event.actorDisplayName?.trim() || event.actorUserId?.trim() || "Unknown",
    occurredAtLabel: formatPragueTimestamp(event.occurredAt),
    before: presentState(event.beforeState, beforeSnapshot, undefined, isPlanningEvent),
    after: presentState(event.afterState, afterSnapshot, beforeSnapshot, isPlanningEvent),
  };
}

function presentState(
  rawState: unknown,
  snapshot: ServiceSnapshot | undefined,
  beforeSnapshot: ServiceSnapshot | undefined,
  isPlanningEvent: boolean,
): AuditStatePresentation {
  if (snapshot) {
    return {
      kind: "service",
      fields: serviceFields(snapshot, beforeSnapshot),
    };
  }

  if (isPlanningEvent || rawState === null || rawState === undefined) {
    return { kind: "empty" };
  }

  return { kind: "generic", text: compactState(rawState) };
}

function serviceFields(snapshot: ServiceSnapshot, before: ServiceSnapshot | undefined): AuditServiceField[] {
  return [
    {
      key: "dateTime",
      text: snapshot.dateTime,
      tone: changedTone(before, snapshot.dateTimeComparable, before?.dateTimeComparable),
    },
    presenceField("antiphon", snapshot.antiphonPresent, snapshot.antiphonComparable, before?.antiphonPresent, before?.antiphonComparable),
    presenceField("topic", snapshot.topicPresent, snapshot.topicComparable, before?.topicPresent, before?.topicComparable),
    presenceField("note", snapshot.notePresent, snapshot.noteComparable, before?.notePresent, before?.noteComparable),
    {
      key: "language",
      text: snapshot.language,
      tone: changedTone(before, snapshot.language, before?.language),
    },
    {
      key: "priest",
      text: `priest ${snapshot.priest || "—"}`,
      tone: changedTone(before, snapshot.priestComparable, before?.priestComparable),
    },
    {
      key: "organist",
      text: `organist ${snapshot.organist || "—"}`,
      tone: changedTone(before, snapshot.organistComparable, before?.organistComparable),
    },
    {
      key: "rows",
      text: `rows: ${snapshot.rowsText}`,
      tone: changedTone(before, snapshot.rowsComparable, before?.rowsComparable),
    },
    {
      key: "lifecycle",
      text: snapshot.lifecycle,
      tone: changedTone(before, snapshot.lifecycle, before?.lifecycle),
    },
  ];
}

function presenceField(
  key: "antiphon" | "topic" | "note",
  present: boolean,
  comparable: string,
  beforePresent: boolean | undefined,
  beforeComparable: string | undefined,
): AuditServiceField {
  if (!present) return { key, text: key, tone: "muted" };
  const changedNonEmpty = beforePresent === true && beforeComparable !== comparable;
  return { key, text: key, tone: changedNonEmpty ? "changed" : "normal" };
}

function changedTone(
  before: ServiceSnapshot | undefined,
  afterComparable: string,
  beforeComparable: string | undefined,
): AuditFieldTone {
  return before && beforeComparable !== afterComparable ? "changed" : "normal";
}

function extractServiceSnapshot(value: unknown): ServiceSnapshot | undefined {
  if (!isRecord(value) || !isRecord(value.serviceContext)) return undefined;

  const nestedSet = isRecord(value.set) ? value.set : undefined;
  const rows = Array.isArray(value.rows)
    ? value.rows
    : nestedSet && Array.isArray(nestedSet.rows)
      ? nestedSet.rows
      : undefined;
  if (!rows) return undefined;

  const context = value.serviceContext;
  const serviceDate = stringValue(context.serviceDate);
  const serviceTime = stringValue(context.serviceTime);
  const language = stringValue(context.language)
    || stringValue(value.language)
    || (nestedSet ? stringValue(nestedSet.language) : "");
  const priest = displayName(context.priest);
  const organist = displayName(context.organist);

  const antiphonValue = context.referenceAntiphon ?? context.antiphonKey ?? null;
  const topicValue = context.referenceTopic ?? null;
  const noteValue = typeof context.note === "string" ? context.note.trim() : "";
  const completed = nestedSet !== undefined && ("sourceFinalSetId" in value || "completedAt" in value);
  const rawStatus = stringValue(value.status) || (nestedSet ? stringValue(nestedSet.status) : "");

  const lifecycle: LifecycleLabel = completed
    ? "Completed Service"
    : rawStatus === "final"
      ? "Final Plan"
      : "Working Plan";


  return {
    dateTime: `${serviceDate || "date missing"} ${serviceTime || "time missing"}`,
    dateTimeComparable: stableStringify([serviceDate, serviceTime]),
    language: language || "language missing",
    priest,
    priestComparable: stableStringify(context.priest ?? null),
    organist,
    organistComparable: stableStringify(context.organist ?? null),
    antiphonPresent: hasMeaningfulValue(antiphonValue),
    antiphonComparable: stableStringify(antiphonValue),
    topicPresent: hasMeaningfulValue(topicValue),
    topicComparable: stableStringify(topicValue),
    notePresent: noteValue.length > 0,
    noteComparable: noteValue,
    rowsText: formatPlanningRowsText(rows),
    rowsComparable: stableStringify(rows),
    lifecycle,
  };
}

function displayName(value: unknown): string {
  if (!isRecord(value)) return "";
  return stringValue(value.displayName);
}

function hasMeaningfulValue(value: unknown): boolean {
  if (value === null || value === undefined) return false;
  if (typeof value === "string") return value.trim().length > 0;
  return true;
}

function formatPragueTimestamp(value: Date): string {
  return value.toLocaleString("cs-CZ", {
    timeZone: "Europe/Prague",
    day: "numeric",
    month: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function compactState(value: unknown): string {
  try { return JSON.stringify(value); }
  catch { return String(value); }
}

function stableStringify(value: unknown): string {
  return JSON.stringify(sortValue(value));
}

function sortValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortValue);
  if (!isRecord(value)) return value;
  return Object.fromEntries(Object.keys(value).sort().map((key) => [key, sortValue(value[key])]));
}

function stringValue(value: unknown): string {
  if (typeof value === "string") return value.trim();
  if (typeof value === "number") return String(value);
  return "";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

import type { Pool, PoolClient } from "pg";
import type { ActorIdentity } from "./interaction-contracts";

export type AuditActorSnapshot =
  | { kind: "system" }
  | { kind: "human"; userId: string; displayName: string; role: string; personId?: string };

export type AuditEventInput = {
  actor: AuditActorSnapshot;
  action: string;
  objectKind: string;
  objectRef: string;
  beforeState?: unknown;
  afterState?: unknown;
};

export type AuditEventRecord = {
  id: number;
  occurredAt: Date;
  actorKind: "human" | "system";
  actorUserId: string | null;
  actorDisplayName: string | null;
  actorRole: string | null;
  actorPersonId: string | null;
  action: string;
  objectKind: string;
  objectRef: string;
  beforeState: unknown | null;
  afterState: unknown | null;
};

type Queryable = Pick<Pool, "query"> | Pick<PoolClient, "query">;

export function humanAuditActor(actor: ActorIdentity): AuditActorSnapshot {
  return {
    kind: "human",
    userId: actor.userId,
    displayName: actor.displayName,
    role: actor.role,
    ...(actor.personId ? { personId: actor.personId } : {}),
  };
}

export function systemAuditActor(): AuditActorSnapshot { return { kind: "system" }; }

export function canReadAuditHistory(roles: readonly string[]): boolean {
  return roles.includes("admin");
}

export function auditEventValues(input: AuditEventInput) {
  return {
    actorKind: input.actor.kind,
    actorUserId: input.actor.kind === "human" ? input.actor.userId : null,
    actorDisplayName: input.actor.kind === "human" ? input.actor.displayName : null,
    actorRole: input.actor.kind === "human" ? input.actor.role : null,
    actorPersonId: input.actor.kind === "human" ? input.actor.personId ?? null : null,
    action: input.action,
    objectKind: input.objectKind,
    objectRef: input.objectRef,
    beforeState: input.beforeState ?? null,
    afterState: input.afterState ?? null,
  };
}

export async function appendAuditEvent(db: Queryable, input: AuditEventInput): Promise<void> {
  const value = auditEventValues(input);
  await db.query(
    `insert into audit_events
      (actor_kind, actor_user_id, actor_display_name, actor_role, actor_person_id, action, object_kind, object_ref, before_state, after_state)
     values ($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10::jsonb)`,
    [
      value.actorKind,
      value.actorUserId,
      value.actorDisplayName,
      value.actorRole,
      value.actorPersonId,
      value.action,
      value.objectKind,
      value.objectRef,
      value.beforeState === null ? null : JSON.stringify(value.beforeState),
      value.afterState === null ? null : JSON.stringify(value.afterState),
    ],
  );
}

export async function listAuditEvents(db: Queryable, limit = 200): Promise<AuditEventRecord[]> {
  const safeLimit = Number.isInteger(limit) ? Math.max(1, Math.min(limit, 1000)) : 200;
  const { rows } = await db.query(
    `select id, occurred_at, actor_kind, actor_user_id, actor_display_name, actor_role, actor_person_id,
            action, object_kind, object_ref, before_state, after_state
       from audit_events
      order by occurred_at desc, id desc
      limit $1`,
    [safeLimit],
  );
  return mapAuditRows(rows);
}

export async function listPlanningAuditEvents(db: Queryable): Promise<AuditEventRecord[]> {
  const { rows } = await db.query(
    `select id, occurred_at, actor_kind, actor_user_id, actor_display_name, actor_role, actor_person_id,
            action, object_kind, object_ref, before_state, after_state
       from audit_events
      where action like 'planning.%'
      order by occurred_at asc, id asc`,
  );
  return mapAuditRows(rows);
}

function mapAuditRows(rows: Record<string, unknown>[]): AuditEventRecord[] {
  return rows.map((row) => ({
    id: Number(row.id),
    occurredAt: row.occurred_at instanceof Date ? row.occurred_at : new Date(String(row.occurred_at)),
    actorKind: row.actor_kind as "human" | "system",
    actorUserId: row.actor_user_id === null ? null : String(row.actor_user_id),
    actorDisplayName: row.actor_display_name === null ? null : String(row.actor_display_name),
    actorRole: row.actor_role === null ? null : String(row.actor_role),
    actorPersonId: row.actor_person_id === null ? null : String(row.actor_person_id),
    action: String(row.action),
    objectKind: String(row.object_kind),
    objectRef: String(row.object_ref),
    beforeState: row.before_state ?? null,
    afterState: row.after_state ?? null,
  }));
}

import type { Pool, PoolClient } from "pg";

export const AUDIT_RETENTION_SUCCESS_ACTION = "maintenance.audit-retention.success";
export const AUDIT_RETENTION_FAILURE_ACTION = "maintenance.audit-retention.failure";
export const AUDIT_RETENTION_OBJECT_KIND = "auditRetentionMaintenance";

export type AuditRetentionDryRunReport = {
  eligible: boolean;
  completedServiceCountConsidered: number;
  cutoffServiceDate: string | null;
  planningAuditCandidates: number;
  resolvedFailureCandidates: number;
  protectedSuccessEvents: number;
};

export type AuditRetentionIncident = {
  id: number;
  occurredAt: Date;
  objectRef: string;
  afterState: unknown | null;
};

type Queryable = Pick<Pool, "query"> | Pick<PoolClient, "query">;

export async function auditRetentionDryRun(db: Queryable): Promise<AuditRetentionDryRunReport> {
  const completed = await db.query(`
    select sc.service_date::text as service_date
      from completed_services cs
      join service_contexts sc on sc.id = cs.service_context_id
     order by sc.service_date desc, coalesce(sc.service_time, time '00:00') desc, cs.id desc
     limit 5
  `);

  if (completed.rows.length < 5) {
    return {
      eligible: false,
      completedServiceCountConsidered: completed.rows.length,
      cutoffServiceDate: null,
      planningAuditCandidates: 0,
      resolvedFailureCandidates: 0,
      protectedSuccessEvents: await countProtectedSuccessEvents(db),
    };
  }

  const cutoffServiceDate = String(completed.rows[4].service_date);
  const [planningCandidates, resolvedFailures, protectedSuccessEvents] = await Promise.all([
    db.query(`
      select count(*)::int as count
        from audit_events e
       where e.action like 'planning.%'
         and e.occurred_at < $1::date
         and not (
           e.object_kind = 'planningSet'
           and exists (
             select 1
               from service_sets active_set
              where active_set.id::text = e.object_ref
                and active_set.status in ('working', 'final')
           )
         )
    `, [cutoffServiceDate]),
    db.query(`
      select count(*)::int as count
        from audit_events failure
       where failure.action = $2
         and failure.occurred_at < $1::date
         and exists (
           select 1
             from audit_events success
            where success.action = $3
              and (success.occurred_at, success.id) > (failure.occurred_at, failure.id)
         )
    `, [cutoffServiceDate, AUDIT_RETENTION_FAILURE_ACTION, AUDIT_RETENTION_SUCCESS_ACTION]),
    countProtectedSuccessEvents(db),
  ]);

  return {
    eligible: true,
    completedServiceCountConsidered: completed.rows.length,
    cutoffServiceDate,
    planningAuditCandidates: Number(planningCandidates.rows[0]?.count ?? 0),
    resolvedFailureCandidates: Number(resolvedFailures.rows[0]?.count ?? 0),
    protectedSuccessEvents,
  };
}

export async function getUnresolvedAuditRetentionIncident(db: Queryable): Promise<AuditRetentionIncident | null> {
  const result = await db.query(`
    select failure.id, failure.occurred_at, failure.object_ref, failure.after_state
      from audit_events failure
     where failure.action = $1
       and not exists (
         select 1
           from audit_events success
          where success.action = $2
            and (success.occurred_at, success.id) > (failure.occurred_at, failure.id)
       )
     order by failure.occurred_at desc, failure.id desc
     limit 1
  `, [AUDIT_RETENTION_FAILURE_ACTION, AUDIT_RETENTION_SUCCESS_ACTION]);
  const row = result.rows[0];
  if (!row) return null;
  return {
    id: Number(row.id),
    occurredAt: row.occurred_at instanceof Date ? row.occurred_at : new Date(String(row.occurred_at)),
    objectRef: String(row.object_ref),
    afterState: row.after_state ?? null,
  };
}

async function countProtectedSuccessEvents(db: Queryable): Promise<number> {
  const result = await db.query(
    "select count(*)::int as count from audit_events where action = $1",
    [AUDIT_RETENTION_SUCCESS_ACTION],
  );
  return Number(result.rows[0]?.count ?? 0);
}

import type { CatalogPerson, CatalogRepository, CatalogSong } from "./catalog";

