export async function seedCatalog(repo: Pick<CatalogRepository, "upsertPerson" | "upsertSong">): Promise<void> {
  for (const person of phase29DemoPeople) await repo.upsertPerson(person);
  for (const song of phase29DemoSongs) await repo.upsertSong(song);
}

import { and, asc, eq, ilike, inArray, or } from "drizzle-orm";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";
import { catalogPersons, catalogSongs } from "../db/schema";
import type * as schema from "../db/schema";
import type { ConcreteSongLanguage, PlanningRole, ServiceLanguage } from "../planning-lifecycle";
import { failure, success, type PlanningServiceResult } from "./planning-lifecycle/results";

export type PersonRole = "priest" | "organist";
export type CatalogPerson = { id: string; displayName: string; active: boolean; priest: boolean; organist: boolean };
export type CatalogSong = { songId: string; language: ConcreteSongLanguage; number: string; title: string; active: boolean; sheetMusicUrl?: string };
export type CatalogSongImportRecord = { language: unknown; number: unknown; title: unknown; active?: unknown; sheetMusicUrl?: unknown };
type CatalogDrizzleDatabase = NodePgDatabase<typeof schema>;
export type CatalogDrizzleExecutor = Pick<CatalogDrizzleDatabase, "select" | "insert" | "update">;
type CatalogPersonRecord = typeof catalogPersons.$inferSelect;
type CatalogSongRecord = typeof catalogSongs.$inferSelect;
export type CatalogImportValidationIssue = { path: string; message: string };

export interface CatalogRepository {
  findPersonById(id: string): Promise<CatalogPerson | undefined>;
  searchPeople(role: PersonRole, query: string): Promise<CatalogPerson[]>;
  listPeople(): Promise<CatalogPerson[]>;
  upsertPerson(person: CatalogPerson): Promise<CatalogPerson>;
  findSongById(id: string): Promise<CatalogSong | undefined>;
  findSongsByIds(ids: string[]): Promise<CatalogSong[]>;
  searchSongs(languages: ConcreteSongLanguage[], query: string): Promise<CatalogSong[]>;
  listSongs(): Promise<CatalogSong[]>;
  upsertSong(song: CatalogSong): Promise<CatalogSong>;
  setSongActive(songId: string, active: boolean): Promise<CatalogSong | undefined>;
}

export class CatalogService {
  constructor(private readonly repo: CatalogRepository) {}
  async getPerson(input: { id: string }) { const person = await this.repo.findPersonById(input.id); return person ? success(person) : failure({ code: "notFound", message: "Person was not found." }); }
  async getSong(input: { songId: string }) { const song = await this.repo.findSongById(input.songId); return song ? success(song) : failure({ code: "notFound", message: "Song was not found." }); }
  async getSongs(input: { songIds: string[] }) { return success(await this.repo.findSongsByIds(input.songIds)); }
  async searchPeople(input: { role: PersonRole; query?: string }) { return success(await this.repo.searchPeople(input.role, input.query ?? "")); }
  async listPeople() { return success(await this.repo.listPeople()); }
  async savePerson(input: { role: PlanningRole; person: Omit<CatalogPerson, "id"> & { id?: string } }): Promise<PlanningServiceResult<CatalogPerson>> {
    if (input.role !== "admin") return failure({ code: "permissionDenied", message: "Only admin can manage person catalog." });
    const name = input.person.displayName.trim();
    if (!name) return failure({ code: "invalidInput", message: "Display name is required." });
    return success(await this.repo.upsertPerson({ id: input.person.id ?? crypto.randomUUID(), displayName: name, active: input.person.active, priest: input.person.priest, organist: input.person.organist }));
  }
  async listSongs() { return success(await this.repo.listSongs()); }
  async searchSongs(input: { language: ServiceLanguage; query?: string }) { return success(await this.repo.searchSongs(languagesForService(input.language), input.query ?? "")); }
  async setSongActive(input: { role: PlanningRole; songId: string; active: boolean }): Promise<PlanningServiceResult<CatalogSong>> {
    if (input.role !== "admin") return failure({ code: "permissionDenied", message: "Only admin can activate or deactivate songs." });
    const song = await this.repo.setSongActive(input.songId, input.active);
    return song ? success(song) : failure({ code: "notFound", message: "Song was not found." });
  }
}

export class InMemoryCatalogRepository implements CatalogRepository {
  constructor(private people = seedPeople(), private songs = seedSongs()) {}
  async findPersonById(id: string) { return this.people.find((p) => p.id === id); }
  async searchPeople(role: PersonRole, query: string) { const q = query.toLowerCase(); return this.people.filter((p) => p.active && p[role] && p.displayName.toLowerCase().includes(q)); }
  async listPeople() { return [...this.people]; }
  async upsertPerson(person: CatalogPerson) { const i = this.people.findIndex((p) => p.id === person.id); if (i >= 0) this.people[i] = person; else this.people.push(person); return person; }
  async findSongById(id: string) { return this.songs.find((s) => s.songId === id); }
  async findSongsByIds(ids: string[]) { const wanted = new Set(ids); return this.songs.filter((song) => wanted.has(song.songId)); }
  async searchSongs(languages: ConcreteSongLanguage[], query: string) { const q = query.toLowerCase(); return this.songs.filter((s) => s.active && languages.includes(s.language) && (s.number.toLowerCase().includes(q) || s.title.toLowerCase().includes(q))); }
  async listSongs() { return [...this.songs]; }
  async upsertSong(song: CatalogSong) { if (this.songs.some((s) => s.songId !== song.songId && s.language === song.language && s.number === song.number)) throw new Error("Duplicate song language/number."); const i = this.songs.findIndex((s) => s.songId === song.songId); if (i >= 0) this.songs[i] = song; else this.songs.push(song); return song; }
  async setSongActive(songId: string, active: boolean) { const song = await this.findSongById(songId); if (!song) return undefined; song.active = active; return song; }
}

export class DrizzleCatalogRepository implements CatalogRepository {
  constructor(private readonly db: CatalogDrizzleExecutor) {}
  async findPersonById(id: string) { const [r] = await this.db.select().from(catalogPersons).where(eq(catalogPersons.id, id)).limit(1); return r && mapPerson(r); }
  async searchPeople(role: PersonRole, query: string) { const roleCol = role === "priest" ? catalogPersons.priest : catalogPersons.organist; const rows = await this.db.select().from(catalogPersons).where(and(eq(catalogPersons.active, true), eq(roleCol, true), ilike(catalogPersons.displayName, `%${query}%`))).orderBy(asc(catalogPersons.displayName)); return rows.map(mapPerson); }
  async listPeople() { return (await this.db.select().from(catalogPersons).orderBy(asc(catalogPersons.displayName))).map(mapPerson); }
  async upsertPerson(person: CatalogPerson) { const now = new Date(); const [r] = await this.db.insert(catalogPersons).values({ ...person, createdAt: now, updatedAt: now }).onConflictDoUpdate({ target: catalogPersons.id, set: { displayName: person.displayName, active: person.active, priest: person.priest, organist: person.organist, updatedAt: now } }).returning(); return mapPerson(r); }
  async findSongById(id: string) { const [r] = await this.db.select().from(catalogSongs).where(eq(catalogSongs.songId, id)).limit(1); return r && mapSong(r); }
  async findSongsByIds(ids: string[]) { if (ids.length === 0) return []; return (await this.db.select().from(catalogSongs).where(inArray(catalogSongs.songId, ids))).map(mapSong); }
  async searchSongs(languages: ConcreteSongLanguage[], query: string) { const rows = await this.db.select().from(catalogSongs).where(and(eq(catalogSongs.active, true), inArray(catalogSongs.language, languages), or(ilike(catalogSongs.number, `%${query}%`), ilike(catalogSongs.title, `%${query}%`)))).orderBy(asc(catalogSongs.language), asc(catalogSongs.number)); return rows.map(mapSong); }
  async listSongs() { return (await this.db.select().from(catalogSongs).orderBy(asc(catalogSongs.language), asc(catalogSongs.number))).map(mapSong); }
  async upsertSong(song: CatalogSong) { const now = new Date(); const [r] = await this.db.insert(catalogSongs).values({ ...song, sheetMusicUrl: song.sheetMusicUrl ?? null, createdAt: now, updatedAt: now }).onConflictDoUpdate({ target: catalogSongs.songId, set: { title: song.title, active: song.active, sheetMusicUrl: song.sheetMusicUrl ?? null, updatedAt: now } }).returning(); return mapSong(r); }
  async setSongActive(songId: string, active: boolean) { const [r] = await this.db.update(catalogSongs).set({ active, updatedAt: new Date() }).where(eq(catalogSongs.songId, songId)).returning(); return r && mapSong(r); }
}

export function languagesForService(language: ServiceLanguage): ConcreteSongLanguage[] { return language === "mixed" ? ["czech", "polish"] : [language]; }
export function isEligiblePerson(person: CatalogPerson | undefined, role: PersonRole) { return Boolean(person?.active && person[role]); }
export async function getEligiblePersonDefaultById(repo: Pick<CatalogRepository, "findPersonById">, id: string | undefined, role: PersonRole): Promise<{ id: string; displayName: string } | undefined> {
  if (!id) return undefined;
  const person = await repo.findPersonById(id);
  return isEligiblePerson(person, role) ? { id: person!.id, displayName: person!.displayName } : undefined;
}
export function isEligibleSong(song: CatalogSong | undefined, serviceLanguage: ServiceLanguage) { return Boolean(song?.active && languagesForService(serviceLanguage).includes(song.language)); }
export function validateCatalogSongImport(input: CatalogSongImportRecord[]): CatalogImportValidationIssue[] { const issues: CatalogImportValidationIssue[] = []; const seen = new Set<string>(); input.forEach((r, i) => { if (r.language !== "czech" && r.language !== "polish") issues.push({ path: `${i}.language`, message: "Unsupported language." }); if (typeof r.number !== "string" || !r.number.trim()) issues.push({ path: `${i}.number`, message: "Number is required." }); if (typeof r.title !== "string" || !r.title.trim()) issues.push({ path: `${i}.title`, message: "Title is required." }); if (r.active !== undefined && typeof r.active !== "boolean") issues.push({ path: `${i}.active`, message: "Active must be a boolean when provided." }); if (r.sheetMusicUrl !== undefined && r.sheetMusicUrl !== null && typeof r.sheetMusicUrl !== "string") issues.push({ path: `${i}.sheetMusicUrl`, message: "Sheet music URL must be a string." }); if (typeof r.sheetMusicUrl === "string" && r.sheetMusicUrl && !/^https?:\/\//.test(r.sheetMusicUrl)) issues.push({ path: `${i}.sheetMusicUrl`, message: "Sheet music URL must be http(s)." }); const key = `${r.language}:${r.number}`; if (seen.has(key)) issues.push({ path: `${i}`, message: "Duplicate language/number in import." }); seen.add(key); }); return issues; }
function mapPerson(r: CatalogPersonRecord): CatalogPerson { return { id: r.id, displayName: r.displayName, active: r.active, priest: r.priest, organist: r.organist }; }
function mapSong(r: CatalogSongRecord): CatalogSong { return { songId: r.songId, language: r.language, number: r.number, title: r.title, active: r.active, ...(r.sheetMusicUrl ? { sheetMusicUrl: r.sheetMusicUrl } : {}) }; }
function seedPeople(): CatalogPerson[] { return [{ id: "demo-priest", displayName: "Demo Priest", active: true, priest: true, organist: false }, { id: "demo-organist", displayName: "Demo Organist", active: true, priest: false, organist: true }, { id: "demo-both", displayName: "Demo Priest Organist", active: true, priest: true, organist: true }, { id: "demo-inactive-priest", displayName: "Demo Inactive Priest", active: false, priest: true, organist: false }]; }
function seedSongs(): CatalogSong[] { return [{ songId: "demo-cz-101", language: "czech", number: "101", title: "Demo Czech Song", active: true, sheetMusicUrl: "https://example.com/cz-101.pdf" }, { songId: "demo-pl-101", language: "polish", number: "101", title: "Demo Polish Song", active: true }, { songId: "demo-cz-inactive", language: "czech", number: "999", title: "Demo Inactive Song", active: false }]; }

import type { CompletedServiceRecord, PersistedPlanningSet, PlanningSetId } from "./planning-lifecycle/ports";
import type { ReferenceMelodyClassProvider } from "./reference-melody-class-provider";

export type CompletedPlanConflictPair = {
  planRowIndex: number;
  completedRowIndex: number;
  reason: string;
};

export type CompletedPlanConflictImpact = {
  planId: PlanningSetId;
  planStatus: "working" | "final";
  completedRecordId: string;
  conflictPairs: CompletedPlanConflictPair[];
  conflictingRowIndexes: number[];
  conflictingCompletedRowIndexes: number[];
  reason: string;
};

export type CompletedPlanInvalidationPreview = {
  impactedPlans: CompletedPlanConflictImpact[];
  newlyImpactedPlans: CompletedPlanConflictImpact[];
};

export async function previewCompletedPlanInvalidation(input: {
  plans: PersistedPlanningSet[];
  currentRecord: CompletedServiceRecord;
  proposedRecord: CompletedServiceRecord;
  melodyClasses: ReferenceMelodyClassProvider;
  months: number;
}): Promise<CompletedPlanInvalidationPreview> {
  const [currentImpacts, proposedImpacts] = await Promise.all([
    findCompletedPlanConflicts(input.plans, [input.currentRecord], input.melodyClasses, input.months),
    findCompletedPlanConflicts(input.plans, [input.proposedRecord], input.melodyClasses, input.months),
  ]);
  const currentPairKeys = new Set(currentImpacts.flatMap((impact) => impact.conflictPairs.map((pair) => conflictPairKey(impact, pair))));
  const newlyImpactedPlans = proposedImpacts.flatMap((impact) => {
    const addedPairs = impact.conflictPairs.filter((pair) => !currentPairKeys.has(conflictPairKey(impact, pair)));
    if (addedPairs.length === 0) return [];
    return [impactFromPairs(impact, addedPairs)];
  });
  return { impactedPlans: proposedImpacts, newlyImpactedPlans };
}

export async function enrichPlanningConflictStates(input: {
  plans: PersistedPlanningSet[];
  completedRecords: CompletedServiceRecord[];
  melodyClasses: ReferenceMelodyClassProvider;
  months: number;
}): Promise<{ plans: PersistedPlanningSet[]; completedRecords: CompletedServiceRecord[] }> {
  const impacts = await findCompletedPlanConflicts(input.plans, input.completedRecords, input.melodyClasses, input.months);
  return {
    plans: applyPlanConflictImpacts(input.plans, impacts),
    completedRecords: applyCompletedConflictImpacts(input.completedRecords, impacts),
  };
}

export async function enrichRevisionRowIndexes(input: {
  plans: PersistedPlanningSet[];
  completedRecords: CompletedServiceRecord[];
  melodyClasses: ReferenceMelodyClassProvider;
  months: number;
}): Promise<PersistedPlanningSet[]> {
  if (input.plans.length === 0) return input.plans;
  const impacts = await findCompletedPlanConflicts(input.plans, input.completedRecords, input.melodyClasses, input.months);
  return applyPlanConflictImpacts(input.plans, impacts);
}

export async function enrichCompletedConflictStates(input: {
  plans: PersistedPlanningSet[];
  completedRecords: CompletedServiceRecord[];
  melodyClasses: ReferenceMelodyClassProvider;
  months: number;
}): Promise<CompletedServiceRecord[]> {
  if (input.completedRecords.length === 0) return input.completedRecords;
  const impacts = await findCompletedPlanConflicts(input.plans, input.completedRecords, input.melodyClasses, input.months);
  return applyCompletedConflictImpacts(input.completedRecords, impacts);
}

export async function findCompletedPlanConflicts(
  plans: PersistedPlanningSet[],
  completedRecords: CompletedServiceRecord[],
  melodyClasses: ReferenceMelodyClassProvider,
  monthsInput: number,
): Promise<CompletedPlanConflictImpact[]> {
  if (plans.length === 0 || completedRecords.length === 0) return [];
  const months = Math.max(0, Math.floor(monthsInput));
  const songIds = [...new Set([
    ...plans.flatMap((plan) => plan.rows.flatMap((row) => row.song?.songId ? [row.song.songId] : [])),
    ...completedRecords.flatMap((record) => record.set.rows.flatMap((row) => row.song?.songId ? [row.song.songId] : [])),
  ])];
  const memberships = await melodyClasses.getClassMemberships(songIds);
  const classBySong = new Map(memberships.map((membership) => [membership.songId, membership.melodyClassId]));
  const melodyClassOf = (songId: string) => classBySong.get(songId) ?? `reference-singleton:${songId}`;
  const impacts: CompletedPlanConflictImpact[] = [];

  for (const plan of plans) {
    for (const record of completedRecords) {
      if (!isWithinCalendarMonths(plan.serviceContext.serviceDate, record.serviceContext.serviceDate, months)) continue;
      const conflictPairs: CompletedPlanConflictPair[] = [];
      for (const [planRowIndex, planRow] of plan.rows.entries()) {
        if (!planRow.song?.songId) continue;
        for (const [completedRowIndex, historicalRow] of record.set.rows.entries()) {
          if (!historicalRow.song?.songId || melodyClassOf(planRow.song.songId) !== melodyClassOf(historicalRow.song.songId)) continue;
          conflictPairs.push({
            planRowIndex,
            completedRowIndex,
            reason: `${plan.serviceContext.serviceDate} ${plan.serviceContext.serviceTime}: song ${planRow.song.number} conflicts with Completed ${record.serviceContext.serviceDate} ${record.serviceContext.serviceTime}, song ${historicalRow.song.number}, within the ${months}-month melody non-repetition period.`,
          });
        }
      }
      if (conflictPairs.length === 0) continue;
      impacts.push(impactFromPairs({
        planId: plan.id,
        planStatus: plan.status,
        completedRecordId: record.id,
        conflictPairs,
        conflictingRowIndexes: [],
        conflictingCompletedRowIndexes: [],
        reason: conflictPairs[0].reason,
      }, conflictPairs));
    }
  }

  return impacts;
}

function applyPlanConflictImpacts(plans: PersistedPlanningSet[], impacts: CompletedPlanConflictImpact[]): PersistedPlanningSet[] {
  const impactsByPlan = new Map<PlanningSetId, CompletedPlanConflictImpact[]>();
  for (const impact of impacts) {
    const planImpacts = impactsByPlan.get(impact.planId) ?? [];
    planImpacts.push(impact);
    impactsByPlan.set(impact.planId, planImpacts);
  }
  return plans.map((plan) => {
    const planImpacts = impactsByPlan.get(plan.id) ?? [];
    if (planImpacts.length === 0) return { ...plan, needsRevision: undefined };
    return {
      ...plan,
      needsRevision: {
        reason: `Needs revision: ${planImpacts.map((impact) => impact.reason).join(" ")}`,
        conflictingCompletedRecordIds: uniqueStrings(planImpacts.map((impact) => impact.completedRecordId)),
        conflictingRowIndexes: uniqueNumbers(planImpacts.flatMap((impact) => impact.conflictingRowIndexes)),
      },
    };
  });
}

function applyCompletedConflictImpacts(completedRecords: CompletedServiceRecord[], impacts: CompletedPlanConflictImpact[]): CompletedServiceRecord[] {
  const impactsByRecord = new Map<string, CompletedPlanConflictImpact[]>();
  for (const impact of impacts) {
    const recordImpacts = impactsByRecord.get(impact.completedRecordId) ?? [];
    recordImpacts.push(impact);
    impactsByRecord.set(impact.completedRecordId, recordImpacts);
  }
  return completedRecords.map((record) => {
    const recordImpacts = impactsByRecord.get(record.id) ?? [];
    if (recordImpacts.length === 0) return { ...record, conflictState: undefined };
    return {
      ...record,
      conflictState: {
        conflictingPlanIds: uniqueStrings(recordImpacts.map((impact) => impact.planId)),
        conflictingRowIndexes: uniqueNumbers(recordImpacts.flatMap((impact) => impact.conflictingCompletedRowIndexes)),
      },
    };
  });
}

function impactFromPairs(impact: CompletedPlanConflictImpact, conflictPairs: CompletedPlanConflictPair[]): CompletedPlanConflictImpact {
  return {
    ...impact,
    conflictPairs,
    conflictingRowIndexes: uniqueNumbers(conflictPairs.map((pair) => pair.planRowIndex)),
    conflictingCompletedRowIndexes: uniqueNumbers(conflictPairs.map((pair) => pair.completedRowIndex)),
    reason: conflictPairs[0]?.reason ?? impact.reason,
  };
}

function conflictPairKey(impact: CompletedPlanConflictImpact, pair: CompletedPlanConflictPair): string {
  return `${impact.planId}�${impact.completedRecordId}�${pair.planRowIndex}�${pair.completedRowIndex}`;
}

function uniqueNumbers(values: number[]): number[] {
  return [...new Set(values)].sort((left, right) => left - right);
}

function uniqueStrings(values: string[]): string[] {
  return [...new Set(values)].sort((left, right) => left.localeCompare(right));
}

function isWithinCalendarMonths(leftDate: string, rightDate: string, months: number): boolean {
  const left = Date.parse(`${leftDate}T00:00:00Z`);
  const right = Date.parse(`${rightDate}T00:00:00Z`);
  if (!Number.isFinite(left) || !Number.isFinite(right)) return false;
  return right >= addMonthsUtc(left, -months) && right <= addMonthsUtc(left, months);
}

function addMonthsUtc(value: number, months: number): number {
  const date = new Date(value);
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, date.getUTCDate());
}

import { createHash } from "node:crypto";
import type { Pool, PoolClient } from "pg";
import { appendAuditEvent } from "./audit-history";

export type CongregationVoterContext = {
  nickname: string;
  userId: string;
  profileId: string;
  role: "congregationMember";
};

export type CongregationVoterSession = {
  context: CongregationVoterContext;
  token: string;
};

export type CongregationOwnPreference = {
  nickname: string;
  referenceSongId: string;
  score: 0 | 1 | null;
  limit: 1;
};

export class CongregationVoterError extends Error {
  constructor(
    readonly code: "invalidInput" | "permissionDenied" | "notFound" | "unauthenticated",
    message: string,
  ) {
    super(message);
    this.name = "CongregationVoterError";
  }
}

export function normalizeCongregationNickname(value: unknown): string {
  if (typeof value !== "string") throw new CongregationVoterError("invalidInput", "Nickname is required.");
  const nickname = value.trim();
  if (!nickname) throw new CongregationVoterError("invalidInput", "Nickname must not be empty.");
  return nickname;
}

function identityForNickname(nickname: string): { userId: string; profileId: string } {
  const digest = createHash("sha256").update(nickname, "utf8").digest("hex");
  return {
    userId: `congregation-voter:${digest}`,
    profileId: `congregation-pref:${digest}`,
  };
}

export class PostgresCongregationPreferenceService {
  constructor(private readonly pool: Pool) {}

  async enterNickname(rawNickname: unknown): Promise<CongregationVoterSession> {
    const nickname = normalizeCongregationNickname(rawNickname);
    const identity = identityForNickname(nickname);
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      const context = await this.ensureVoter(client, nickname, identity.userId, identity.profileId);
      await client.query("commit");
      return { context, token: context.userId };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw error;
    } finally {
      client.release();
    }
  }

  async resolveContext(token: unknown): Promise<CongregationVoterContext> {
    if (typeof token !== "string" || !token.startsWith("congregation-voter:")) {
      throw new CongregationVoterError("unauthenticated", "Enter a nickname to start congregation preference voting.");
    }
    const result = await this.pool.query(
      `select u.id as user_id, u.display_name, u.active, p.id as profile_id,
              coalesce(array_agg(r.role) filter (where r.role is not null), '{}') as roles,
              count(l.auth_user_id)::integer as protected_link_count
       from app_users u
       join preference_profiles p on p.user_id = u.id and p.category = 'congregation_member'
       left join app_user_roles r on r.user_id = u.id
       left join protected_account_actor_links l on l.app_user_id = u.id
       where u.id = $1
       group by u.id, p.id`,
      [token],
    );
    if (result.rows.length !== 1) {
      throw new CongregationVoterError("unauthenticated", "Congregation voter context is missing.");
    }
    const row = result.rows[0];
    const roles = normalizeTextArray(row.roles);
    if (!Boolean(row.active) || Number(row.protected_link_count) !== 0 || roles.length !== 1 || roles[0] !== "congregation_member") {
      throw new CongregationVoterError("permissionDenied", "Congregation voter context cannot authorize protected behavior.");
    }
    return {
      nickname: String(row.display_name),
      userId: String(row.user_id),
      profileId: String(row.profile_id),
      role: "congregationMember",
    };
  }

  async getOwnReferencePreference(token: unknown, referenceSongId: unknown): Promise<CongregationOwnPreference> {
    const songId = validateReferenceSongId(referenceSongId);
    const context = await this.resolveContext(token);
    await this.requireReferenceSong(songId);
    const result = await this.pool.query(
      "select score from reference_song_preferences where profile_id = $1 and reference_song_id = $2",
      [context.profileId, songId],
    );
    const score = result.rows[0] ? Number(result.rows[0].score) : null;
    if (score !== null && score !== 0 && score !== 1) {
      throw new CongregationVoterError("permissionDenied", "Congregation preference profile contains an invalid score.");
    }
    return { nickname: context.nickname, referenceSongId: songId, score, limit: 1 };
  }

  async saveOwnReferencePreference(token: unknown, referenceSongId: unknown, rawScore: unknown): Promise<CongregationOwnPreference> {
    const songId = validateReferenceSongId(referenceSongId);
    const score = validateCongregationScore(rawScore);
    const context = await this.resolveContext(token);
    await this.requireReferenceSong(songId);
    const client = await this.pool.connect();
    try {
      await client.query("begin");
      const existing = await client.query(
        "select score from reference_song_preferences where profile_id = $1 and reference_song_id = $2 for update",
        [context.profileId, songId],
      );
      const beforeScore = existing.rows[0] ? Number(existing.rows[0].score) : null;
      if (beforeScore !== score) {
        await client.query(
          `insert into reference_song_preferences (profile_id, reference_song_id, score)
           values ($1, $2, $3)
           on conflict (profile_id, reference_song_id)
           do update set score = excluded.score, updated_at = now()`,
          [context.profileId, songId, score],
        );
        await appendAuditEvent(client, {
          actor: { kind: "human", userId: context.userId, displayName: context.nickname, role: context.role },
          action: "preference.reference.save",
          objectKind: "referencePreference",
          objectRef: `${context.profileId}:${songId}`,
          beforeState: { score: beforeScore },
          afterState: { score },
        });
      }
      await client.query("commit");
      return { nickname: context.nickname, referenceSongId: songId, score, limit: 1 };
    } catch (error) {
      await client.query("rollback").catch(() => undefined);
      throw error;
    } finally { client.release(); }
  }

  private async ensureVoter(
    client: PoolClient,
    nickname: string,
    userId: string,
    profileId: string,
  ): Promise<CongregationVoterContext> {
    await client.query(
      `insert into app_users (id, display_name, active)
       values ($1, $2, true)
       on conflict (id) do nothing`,
      [userId, nickname],
    );

    const actor = await client.query(
      "select display_name, active from app_users where id = $1 for update",
      [userId],
    );
    if (actor.rows.length !== 1 || String(actor.rows[0].display_name) !== nickname) {
      throw new CongregationVoterError("permissionDenied", "Nickname profile cannot be resolved safely.");
    }
    if (!Boolean(actor.rows[0].active)) {
      throw new CongregationVoterError("permissionDenied", "Nickname profile is inactive.");
    }

    const protectedLink = await client.query(
      "select 1 from protected_account_actor_links where app_user_id = $1 limit 1",
      [userId],
    );
    if (protectedLink.rows.length > 0) {
      throw new CongregationVoterError("permissionDenied", "Nickname profile cannot be linked to a protected Account.");
    }

    const rolesBefore = await client.query(
      "select role from app_user_roles where user_id = $1 order by role",
      [userId],
    );
    const existingRoles = rolesBefore.rows.map((row) => String(row.role));
    if (existingRoles.some((role) => role !== "congregation_member")) {
      throw new CongregationVoterError("permissionDenied", "Nickname profile cannot hold protected roles.");
    }

    await client.query(
      `insert into app_user_roles (user_id, role)
       values ($1, 'congregation_member')
       on conflict (user_id, role) do nothing`,
      [userId],
    );

    await client.query(
      `insert into preference_profiles (id, user_id, category)
       values ($1, $2, 'congregation_member')
       on conflict (user_id) do nothing`,
      [profileId, userId],
    );

    const profile = await client.query(
      "select id, category from preference_profiles where user_id = $1",
      [userId],
    );
    if (
      profile.rows.length !== 1 ||
      String(profile.rows[0].id) !== profileId ||
      String(profile.rows[0].category) !== "congregation_member"
    ) {
      throw new CongregationVoterError("permissionDenied", "Nickname profile cannot reuse a protected preference profile.");
    }

    const rolesAfter = await client.query(
      "select role from app_user_roles where user_id = $1 order by role",
      [userId],
    );
    if (rolesAfter.rows.length !== 1 || String(rolesAfter.rows[0].role) !== "congregation_member") {
      throw new CongregationVoterError("permissionDenied", "Nickname profile must have exactly the congregation-member role.");
    }

    return { nickname, userId, profileId, role: "congregationMember" };
  }

  private async requireReferenceSong(referenceSongId: string): Promise<void> {
    const result = await this.pool.query(
      "select 1 from reference_catalog_songs where id = $1 limit 1",
      [referenceSongId],
    );
    if (result.rows.length !== 1) throw new CongregationVoterError("notFound", "Reference song was not found.");
  }
}

function validateReferenceSongId(value: unknown): string {
  if (typeof value !== "string" || !/^(?:czech|polish):[1-9]\d*$/.test(value)) {
    throw new CongregationVoterError("invalidInput", "A valid referenceSongId is required.");
  }
  return value;
}

function validateCongregationScore(value: unknown): 0 | 1 {
  if (value !== 0 && value !== 1) {
    throw new CongregationVoterError("invalidInput", "Congregation preference score must be 0 or 1.");
  }
  return value;
}

function normalizeTextArray(value: unknown): string[] {
  if (Array.isArray(value)) return value.map(String);
  if (typeof value === "string") return value.replace(/[{}]/g, "").split(",").filter(Boolean);
  return [];
}

import type { Pool } from "pg";
import type { InteractionRepository } from "./interaction-service";
import type { AppUser, KnowledgeMapping, MelodyClass, MelodyNonRepetitionConfig, PreferenceProfile, SongPreference } from "./interaction-contracts";
import type { PlanningRole } from "../planning-lifecycle";

export class PgInteractionRepository implements InteractionRepository {
  constructor(private readonly pool: Pick<Pool, "query">) {}
  async listUsers(): Promise<AppUser[]> { const { rows } = await this.pool.query("select u.id, u.display_name, u.person_id, u.active, coalesce(array_agg(r.role) filter (where r.role is not null), '{}') as roles from app_users u left join app_user_roles r on r.user_id = u.id group by u.id order by u.id"); return rows.map((r) => ({ id: String(r.id), displayName: String(r.display_name), ...(r.person_id ? { personId: String(r.person_id) } : {}), active: Boolean(r.active), roles: normalizeRoles(r.roles) })); }
  async listProfiles(): Promise<PreferenceProfile[]> { const { rows } = await this.pool.query("select id, user_id, category from preference_profiles order by id"); return rows.map((r) => ({ id: String(r.id), userId: String(r.user_id), category: fromDbCategory(String(r.category)) })); }
  async listPreferences(): Promise<SongPreference[]> { const { rows } = await this.pool.query("select profile_id, song_id, score from song_preferences"); return rows.map((r) => ({ profileId: String(r.profile_id), songId: String(r.song_id), score: Number(r.score) })); }
  async upsertPreference(preference: SongPreference): Promise<SongPreference> { await this.pool.query("insert into song_preferences (profile_id, song_id, score) values ($1, $2, $3) on conflict (profile_id, song_id) do update set score = excluded.score, updated_at = now()", [preference.profileId, preference.songId, preference.score]); return preference; }
  async referenceSongExists(referenceSongId: string): Promise<boolean> { const { rows } = await this.pool.query("select 1 from reference_catalog_songs where id = $1", [referenceSongId]); return rows.length === 1; }
  async getReferenceOwnPreference(profileId: string, referenceSongId: string): Promise<number | undefined> { const { rows } = await this.pool.query("select score from reference_song_preferences where profile_id = $1 and reference_song_id = $2", [profileId, referenceSongId]); return rows[0] ? Number(rows[0].score) : undefined; }
  async getReferencePreferenceAggregate(referenceSongId: string): Promise<number> { const { rows } = await this.pool.query("select coalesce(sum(score), 0)::integer as aggregate_preference_score from reference_song_preferences where reference_song_id = $1", [referenceSongId]); return Number(rows[0].aggregate_preference_score); }
  async upsertReferenceOwnPreference(profileId: string, referenceSongId: string, score: number): Promise<number> { await this.pool.query("insert into reference_song_preferences (profile_id, reference_song_id, score) values ($1, $2, $3) on conflict (profile_id, reference_song_id) do update set score = excluded.score, updated_at = now()", [profileId, referenceSongId, score]); return score; }
  async listRepertoire(organistPersonId: string): Promise<string[]> { const { rows } = await this.pool.query("select song_id from organist_repertoire where organist_person_id = $1 order by song_id", [organistPersonId]); return rows.map((r) => String(r.song_id)); }
  async setRepertoire(organistPersonId: string, songId: string, active: boolean): Promise<void> { if (active) await this.pool.query("insert into organist_repertoire (organist_person_id, song_id) values ($1, $2) on conflict do nothing", [organistPersonId, songId]); else await this.pool.query("delete from organist_repertoire where organist_person_id = $1 and song_id = $2", [organistPersonId, songId]); }
  async listMelodyClasses(): Promise<MelodyClass[]> { const { rows } = await this.pool.query("select c.id, c.label, c.synthetic, coalesce(array_agg(s.song_id) filter (where s.song_id is not null), '{}') as song_ids from melody_equivalence_classes c left join song_melody_equivalence s on s.class_id = c.id group by c.id order by c.id"); return rows.map((r) => ({ id: String(r.id), label: String(r.label), synthetic: Boolean(r.synthetic), songIds: normalizeTextArray(r.song_ids) })); }
  async listKnowledge(): Promise<{ antiphons: KnowledgeMapping[]; seasons: KnowledgeMapping[]; melodyWindow: MelodyNonRepetitionConfig; melodyClasses: MelodyClass[] }> { const [antiphons, seasons, melodyWindow, melodyClasses] = await Promise.all([this.listMappings("antiphon_mappings", "antiphon_key"), this.listMappings("liturgical_season_mappings", "season_key"), this.getMelodyWindow(), this.listMelodyClasses()]); return { antiphons, seasons, melodyWindow, melodyClasses }; }
  async setMelodyWindow(config: MelodyNonRepetitionConfig): Promise<MelodyNonRepetitionConfig> { await this.pool.query("insert into melody_non_repetition_config (id, months) values ('global', $1) on conflict (id) do update set months = excluded.months, updated_at = now()", [config.months]); return config; }
  private async getMelodyWindow() { const { rows } = await this.pool.query("select months from melody_non_repetition_config where id = 'global'"); return rows[0] ? { months: Number(rows[0].months) } : { months: 2 }; }
  private async listMappings(table: "antiphon_mappings" | "liturgical_season_mappings", keyColumn: "antiphon_key" | "season_key"): Promise<KnowledgeMapping[]> { const { rows } = await this.pool.query(`select id, ${keyColumn} as key, song_id, synthetic from ${table} order by id`); return rows.map((r) => ({ id: String(r.id), key: String(r.key), songId: String(r.song_id), synthetic: Boolean(r.synthetic) })); }
}
function fromDbCategory(category: string): "priest" | "organist" | "congregationMember" { return category === "congregation_member" ? "congregationMember" : category as "priest" | "organist"; }
function normalizeRoles(value: unknown): PlanningRole[] { return normalizeTextArray(value).map((role) => role === "congregation_member" ? "congregationMember" : role as PlanningRole); }
function normalizeTextArray(value: unknown): string[] { return Array.isArray(value) ? value.map(String) : typeof value === "string" ? value.replace(/[{}]/g, "").split(",").filter(Boolean) : []; }

import type { CatalogSong } from "./catalog";
import type { ConcreteSongLanguage, PlanningRole, ServiceLanguage } from "../planning-lifecycle";
import { languagesForService } from "./catalog";

export type PreferenceProfileCategory = "priest" | "organist" | "congregationMember";
export type AppUser = { id: string; displayName: string; personId?: string; roles: PlanningRole[]; active: boolean; whatsappPhone?: string };
export type ActorIdentity = { userId: string; displayName: string; role: PlanningRole; personId?: string };
export type PreferenceProfile = { id: string; userId: string; category: PreferenceProfileCategory };
export type SongPreference = { profileId: string; songId: string; score: number };
export type ReferenceOwnPreference = { referenceSongId: string; category: PreferenceProfileCategory; score: number | null; limit: number };
export type ReferencePreferenceAggregate = { referenceSongId: string; aggregateScore: number };
export type MelodyClass = { id: string; label: string; songIds: string[]; synthetic: boolean };
export type KnowledgeMapping = { id: string; key: string; songId: string; synthetic: boolean };
export type MelodyNonRepetitionConfig = { months: number };
export type CandidateUsageSource = "completed" | "working" | "final" | "current";
export type CandidateUsage = { songId: string; serviceDate: string; source: CandidateUsageSource; planId?: string; rowId?: number; rowLabel?: string };
export type CandidateQueryInput = { serviceDate: string; serviceLanguage: ServiceLanguage; organistPersonId?: string; referenceAntiphonId?: string; referenceTopicId?: string; antiphonKey?: string; liturgicalSeasonKey?: string; queryText?: string; preferenceThreshold?: number; currentPlanId?: string; candidateUsages?: CandidateUsage[]; historicalTruth?: boolean };
export type CatalogCandidateAvailabilityMode = "available" | "unavailable";
export type CatalogCandidateQueryInput = { serviceLanguage: ServiceLanguage; organistPersonId?: string; referenceAntiphonId?: string; referenceTopicId?: string; queryText?: string; availabilityMode: CatalogCandidateAvailabilityMode };
export type CandidateMelodyMember = { songId: string; language: ConcreteSongLanguage; number: string; title: string; repertoire: boolean; aggregatePreferenceScore: number; sheetMusicUrl?: string };
export type CandidateOccupyingRow = { rowId: number; label: string };
export type CandidateAvailability = { kind: "available" } | { kind: "occupiedByCurrentRows"; rows: CandidateOccupyingRow[] };
export type CandidateQueryResult = { songId: string; language: ConcreteSongLanguage; number: string; title: string; equivalentNumbers: { songId: string; number: string; repertoire: boolean }[]; melodyClassId?: string; melodyMembers?: CandidateMelodyMember[]; aggregatePreferenceScore: number; antiphonMatch: boolean; seasonMatch: boolean; signal: "antiphon" | "season" | "none"; preferenceShade: "none" | "low" | "medium" | "high"; repertoire: boolean; availability: CandidateAvailability; suppressedByMelodyWindow: boolean; sheetMusicUrl?: string; orderKey: string };
export type CandidateHydrationInput = { songs: { songId?: string; language: ConcreteSongLanguage; number: string; title?: string }[]; organistPersonId?: string; referenceAntiphonId?: string; referenceTopicId?: string; antiphonKey?: string; liturgicalSeasonKey?: string };

export function preferenceScoreLimit(category: PreferenceProfileCategory): number { return category === "priest" ? 3 : category === "organist" ? 2 : 1; }
export function validateOwnPreferenceScore(category: PreferenceProfileCategory, score: number): boolean { return Number.isInteger(score) && score >= 0 && score <= preferenceScoreLimit(category); }
export function canManageKnowledge(role: PlanningRole): boolean { return role === "admin"; }
export function canManageRepertoire(actor: { role: PlanningRole; personId?: string }, organistPersonId: string): boolean { return actor.role === "admin" || (actor.role === "organist" && actor.personId === organistPersonId); }
export function getPreferenceShade(score: number): CandidateQueryResult["preferenceShade"] { return score >= 6 ? "high" : score >= 3 ? "medium" : score > 0 ? "low" : "none"; }
export function getCandidateSignal(input: { antiphonMatch: boolean; seasonMatch: boolean }): CandidateQueryResult["signal"] { return input.antiphonMatch ? "antiphon" : input.seasonMatch ? "season" : "none"; }

export type RowLookupState = { kind: "empty" } | { kind: "selected"; songId: string } | { kind: "noteOnly"; note: string } | { kind: "lookup"; text: string; previous?: Exclude<RowLookupState, { kind: "lookup" }> };
export function isValidRowState(row: RowLookupState): boolean { return row.kind !== "lookup" && (row.kind !== "noteOnly" || row.note.trim().length > 0); }
export function cancelLookup(row: RowLookupState): RowLookupState { return row.kind === "lookup" ? row.previous ?? { kind: "empty" } : row; }
export function canLeaveWorkspace(rows: RowLookupState[]): { allowed: boolean; reason?: string } { return rows.some((r) => r.kind === "lookup" && r.text.trim()) ? { allowed: false, reason: "Select a candidate or cancel the active lookup before leaving Planning." } : { allowed: true }; }
export function canAddOrPersistRows(rows: RowLookupState[]): boolean { return rows.every(isValidRowState); }
export function restoreLookupOnCancel<T extends { lookupOpen?: boolean; songSearch: string; selectedSong?: { language: ConcreteSongLanguage; number: string; title?: string }; note: string }>(row: T): T { return { ...row, lookupOpen: false, songSearch: row.selectedSong ? `${row.selectedSong.language} ${row.selectedSong.number}${row.selectedSong.title ? ` — ${row.selectedSong.title}` : ""}` : "" }; }
export function restoreRowsForRowSwitch<T extends { id: number; lookupOpen?: boolean; songSearch: string; selectedSong?: { language: ConcreteSongLanguage; number: string; title?: string }; note: string }>(rows: T[], targetRowId: number): T[] { return rows.map((row) => row.id === targetRowId ? row : row.lookupOpen ? restoreLookupOnCancel(row) : row); }

export class InMemoryInteractionRepository {
  readonly users: AppUser[] = [
    { id: "demo-priest-user", displayName: "Demo Priest User", personId: "demo-priest", roles: ["priest"], active: true },
    { id: "demo-organist-user", displayName: "Demo Organist User", personId: "demo-organist", roles: ["organist"], active: true },
    { id: "demo-admin-user", displayName: "Demo Admin User", roles: ["admin"], active: true },
    { id: "demo-member-user", displayName: "Demo Congregation User", roles: ["congregationMember"], active: true },
  ];
  readonly profiles: PreferenceProfile[] = [
    { id: "pref-priest", userId: "demo-priest-user", category: "priest" },
    { id: "pref-organist", userId: "demo-organist-user", category: "organist" },
    { id: "pref-member", userId: "demo-member-user", category: "congregationMember" },
  ];
  private preferences = new Map<string, SongPreference>();
  private repertoire = new Set<string>();
  private melodyClasses: MelodyClass[] = [];
  private antiphons: KnowledgeMapping[] = [];
  private seasons: KnowledgeMapping[] = [];
  private melodyWindow: MelodyNonRepetitionConfig = { months: 2 };

  constructor() {
    this.preferences.set(this.preferenceKey("pref-priest", "demo-cz-101"), { profileId: "pref-priest", songId: "demo-cz-101", score: 3 });
    this.preferences.set(this.preferenceKey("pref-organist", "demo-cz-101"), { profileId: "pref-organist", songId: "demo-cz-101", score: 2 });
    this.preferences.set(this.preferenceKey("pref-member", "demo-cz-101"), { profileId: "pref-member", songId: "demo-cz-101", score: 1 });
    this.repertoire.add(this.repertoireKey("demo-organist", "demo-cz-101"));
    this.melodyClasses = [{ id: "synthetic-melody-a", label: "Synthetic melody A", songIds: ["demo-cz-101", "demo-pl-101"], synthetic: true }];
    this.antiphons = [{ id: "synthetic-antiphon-entry", key: "synthetic-entry", songId: "demo-cz-101", synthetic: true }];
    this.seasons = [{ id: "synthetic-season-advent", key: "synthetic-advent", songId: "demo-pl-101", synthetic: true }];
  }

  listUsers(): AppUser[] { return this.users.map((u) => ({ ...u, roles: [...u.roles] })); }
  resolveActor(userId: string, requestedRole?: PlanningRole): ActorIdentity | undefined { const user = this.users.find((u) => u.id === userId && u.active); if (!user) return undefined; const role = requestedRole && user.roles.includes(requestedRole) ? requestedRole : user.roles[0]; return role ? { userId: user.id, displayName: user.displayName, role, ...(user.personId ? { personId: user.personId } : {}) } : undefined; }
  listPreferences(): SongPreference[] { return [...this.preferences.values()].map((p) => ({ ...p })); }
  saveOwnPreference(actor: ActorIdentity, songId: string, score: number): SongPreference | undefined { const profile = this.profiles.find((p) => p.userId === actor.userId); if (!profile || !validateOwnPreferenceScore(profile.category, score)) return undefined; const pref = { profileId: profile.id, songId, score }; this.preferences.set(this.preferenceKey(profile.id, songId), pref); return { ...pref }; }
  setRepertoire(actor: ActorIdentity, organistPersonId: string, songId: string, active: boolean): boolean { if (!canManageRepertoire(actor, organistPersonId)) return false; const key = this.repertoireKey(organistPersonId, songId); if (active) this.repertoire.add(key); else this.repertoire.delete(key); return true; }
  listRepertoire(organistPersonId: string): string[] { return [...this.repertoire].filter((key) => key.startsWith(`${organistPersonId}:`)).map((key) => key.split(":")[1]); }
  listMelodyClasses(): MelodyClass[] { return this.melodyClasses.map((m) => ({ ...m, songIds: [...m.songIds] })); }
  getMelodyWindow(): MelodyNonRepetitionConfig { return { ...this.melodyWindow }; }
  setMelodyWindow(actor: ActorIdentity, config: MelodyNonRepetitionConfig): boolean { if (!canManageKnowledge(actor.role) || config.months < 0) return false; this.melodyWindow = { months: Math.floor(config.months) }; return true; }
  addKnowledgeMapping(actor: ActorIdentity, kind: "antiphon" | "season", mapping: KnowledgeMapping): boolean { if (!canManageKnowledge(actor.role)) return false; if (kind === "antiphon") this.antiphons.push({ ...mapping, synthetic: true }); else this.seasons.push({ ...mapping, synthetic: true }); return true; }
  listKnowledge() { return { antiphons: this.antiphons.map((m) => ({ ...m })), seasons: this.seasons.map((m) => ({ ...m })), melodyWindow: this.getMelodyWindow(), melodyClasses: this.listMelodyClasses() }; }

  queryCandidates(songs: CatalogSong[], input: CandidateQueryInput): CandidateQueryResult[] {
    if (input.historicalTruth) return queryHistoricalTruthCatalogCandidates(songs, input.serviceLanguage, input.queryText);
    const organistPersonId = input.organistPersonId;
    const languageSet = new Set(languagesForService(input.serviceLanguage));
    const recentClassIds = getRecentMelodyClassIds(this.melodyClasses, input, this.melodyWindow);
    const queryText = input.queryText?.trim().toLowerCase();
    const threshold = input.preferenceThreshold ?? 0;
    const songsById = new Map(songs.map((song) => [song.songId, song]));
    const groups = new Map<string, CatalogSong[]>();
    for (const song of songs) {
      if (!song.active || !languageSet.has(song.language)) continue;
      const melody = this.melodyClasses.find((m) => m.songIds.includes(song.songId));
      const classId = melody?.id ?? `song:${song.songId}`;
      if (melody && recentClassIds.has(melody.id)) continue;
      groups.set(classId, [...(groups.get(classId) ?? []), song]);
    }
    const candidates: CandidateQueryResult[] = [];
    for (const [classId, groupSongs] of groups) {
      const melody = this.melodyClasses.find((m) => m.id === classId);
      const allClassSongIds = melody?.songIds ?? groupSongs.map((song) => song.songId);
      if (organistPersonId && !allClassSongIds.some((songId) => this.repertoire.has(this.repertoireKey(organistPersonId, songId)))) continue;
      const scored = groupSongs.map((song) => {
        const aggregatePreferenceScore = [...this.preferences.values()].filter((p) => p.songId === song.songId).reduce((sum, p) => sum + p.score, 0);
        const antiphonMatch = Boolean(input.antiphonKey && this.antiphons.some((m) => m.key === input.antiphonKey && m.songId === song.songId));
        const seasonMatch = Boolean(input.liturgicalSeasonKey && this.seasons.some((m) => m.key === input.liturgicalSeasonKey && m.songId === song.songId));
        return { song, aggregatePreferenceScore, antiphonMatch, seasonMatch, signal: getCandidateSignal({ antiphonMatch, seasonMatch }), repertoire: input.organistPersonId ? this.repertoire.has(this.repertoireKey(input.organistPersonId, song.songId)) : false };
      });
      if (Math.max(...scored.map((item) => item.aggregatePreferenceScore), 0) < threshold) continue;
      if (queryText && !scored.some((item) => item.song.number.toLowerCase().includes(queryText) || item.song.title.toLowerCase().includes(queryText))) continue;
      scored.sort((a, b) => `${a.repertoire ? 0 : 1}:${a.signal === "antiphon" ? 0 : a.signal === "season" ? 1 : 2}:${999 - a.aggregatePreferenceScore}:${a.song.language}:${a.song.number}`.localeCompare(`${b.repertoire ? 0 : 1}:${b.signal === "antiphon" ? 0 : b.signal === "season" ? 1 : 2}:${999 - b.aggregatePreferenceScore}:${b.song.language}:${b.song.number}`));
      const primary = scored[0];
      const equivalentNumbers = allClassSongIds.filter((songId) => songId !== primary.song.songId).map((songId) => ({ songId, number: songsById.get(songId)?.number ?? songId, repertoire: input.organistPersonId ? this.repertoire.has(this.repertoireKey(input.organistPersonId, songId)) : false })).sort((a, b) => `${a.repertoire ? 0 : 1}:${a.number}`.localeCompare(`${b.repertoire ? 0 : 1}:${b.number}`));
      candidates.push({ songId: primary.song.songId, language: primary.song.language, number: primary.song.number, title: primary.song.title, equivalentNumbers, aggregatePreferenceScore: primary.aggregatePreferenceScore, antiphonMatch: primary.antiphonMatch, seasonMatch: primary.seasonMatch, signal: primary.signal, preferenceShade: getPreferenceShade(primary.aggregatePreferenceScore), repertoire: primary.repertoire, availability: availabilityForClass(this.melodyClasses, classId, input.candidateUsages ?? []), suppressedByMelodyWindow: false, ...(primary.song.sheetMusicUrl ? { sheetMusicUrl: primary.song.sheetMusicUrl } : {}), orderKey: `${primary.signal === "antiphon" ? 0 : primary.signal === "season" ? 1 : 2}:${primary.repertoire ? 0 : 1}:${999 - primary.aggregatePreferenceScore}:${primary.song.language}:${primary.song.number}` });
    }
    return candidates.sort((a, b) => a.orderKey.localeCompare(b.orderKey));
  }

  createSyntheticScaleSongs(count: number): CatalogSong[] { return Array.from({ length: count }, (_, index) => ({ songId: `synthetic-scale-${index + 1}`, language: index % 2 === 0 ? "czech" : "polish", number: `SYN-${String(index + 1).padStart(5, "0")}`, title: `Synthetic Scale Song ${index + 1}`, active: true })); }
  private preferenceKey(profileId: string, songId: string) { return `${profileId}:${songId}`; }
  private repertoireKey(personId: string, songId: string) { return `${personId}:${songId}`; }
}

function queryHistoricalTruthCatalogCandidates(songs: CatalogSong[], serviceLanguage: ServiceLanguage, queryText?: string): CandidateQueryResult[] {
  const query = queryText?.trim().toLocaleLowerCase() ?? "";
  const zeroLanguage: ConcreteSongLanguage = serviceLanguage === "polish" ? "polish" : "czech";
  const zeroCandidate: CandidateQueryResult = {
    songId: `historical-zero:${zeroLanguage}`,
    language: zeroLanguage,
    number: "0",
    title: "Historical zero value",
    equivalentNumbers: [],
    aggregatePreferenceScore: 0,
    antiphonMatch: false,
    seasonMatch: false,
    signal: "none",
    preferenceShade: "none",
    repertoire: false,
    availability: { kind: "available" },
    suppressedByMelodyWindow: false,
    orderKey: "historical:0",
  };
  const concrete = songs
    .filter((song) => !query || song.number.toLocaleLowerCase().includes(query) || song.title.toLocaleLowerCase().includes(query))
    .map((song): CandidateQueryResult => ({
      songId: song.songId,
      language: song.language,
      number: song.number,
      title: song.title,
      equivalentNumbers: [],
      aggregatePreferenceScore: 0,
      antiphonMatch: false,
      seasonMatch: false,
      signal: "none",
      preferenceShade: "none",
      repertoire: false,
      availability: { kind: "available" },
      suppressedByMelodyWindow: false,
      ...(song.sheetMusicUrl ? { sheetMusicUrl: song.sheetMusicUrl } : {}),
      orderKey: `historical:1:${song.language}:${song.number}:${song.songId}`,
    }));
  const includeZero = !query || zeroCandidate.number.includes(query) || zeroCandidate.title.toLocaleLowerCase().includes(query);
  return [...(includeZero ? [zeroCandidate] : []), ...concrete]
    .sort((left, right) => left.orderKey.localeCompare(right.orderKey, undefined, { numeric: true }));
}

function getRecentMelodyClassIds(classes: MelodyClass[], input: CandidateQueryInput, window: MelodyNonRepetitionConfig): Set<string> {
  const ids = new Set<string>();
  const target = Date.parse(`${input.serviceDate}T00:00:00Z`);
  const datedUsages = (input.candidateUsages ?? []).filter((usage) => usage.source !== "current" && (!input.currentPlanId || usage.planId !== input.currentPlanId));
  for (const recent of datedUsages) {
    if (!isWithinSymmetricTwoCalendarMonths(target, Date.parse(`${recent.serviceDate}T00:00:00Z`), window.months)) continue;
    for (const melody of classes) if (melody.songIds.includes(recent.songId)) ids.add(melody.id);
  }
  return ids;
}

function isWithinSymmetricTwoCalendarMonths(target: number, usedAt: number, months = 2): boolean { const earlier = addMonthsUtc(target, -months); const later = addMonthsUtc(target, months); return usedAt >= earlier && usedAt <= later; }
function addMonthsUtc(value: number, months: number): number { const date = new Date(value); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, date.getUTCDate()); }

function availabilityForClass(classes: MelodyClass[], classId: string, usages: CandidateUsage[]): CandidateAvailability {
  const rows = usages
    .filter((usage) => usage.source === "current" && classIdForSong(classes, usage.songId) === classId && usage.rowId !== undefined && usage.rowLabel)
    .map((usage) => ({ rowId: usage.rowId!, label: usage.rowLabel!.trim() }))
    .filter((row, index, all) => all.findIndex((candidate) => candidate.rowId === row.rowId) === index)
    .sort((left, right) => left.rowId - right.rowId || left.label.localeCompare(right.label));
  return rows.length > 0 ? { kind: "occupiedByCurrentRows", rows } : { kind: "available" };
}

function classIdForSong(classes: MelodyClass[], songId: string): string {
  return classes.find((melody) => melody.songIds.includes(songId))?.id ?? `song:${songId}`;
}

import type { Pool } from "pg";

