    await client.query("insert into catalog_persons (id, display_name, active, priest, organist) values ($1, $2, true, false, true) on conflict (id) do update set display_name = excluded.display_name, active = true, priest = false, organist = true, updated_at = now()", ["demo-organist", "Demo Organist"]);
    await client.query("insert into catalog_songs (song_id, language, number, title, active, sheet_music_url) values ($1, 'czech', $2, $3, true, $4) on conflict (song_id) do update set language = excluded.language, number = excluded.number, title = excluded.title, active = true, sheet_music_url = excluded.sheet_music_url, updated_at = now()", ["demo-cz-101", "101", "Demo Czech Song", "https://example.com/cz-101.pdf"]);
    await client.query("insert into catalog_songs (song_id, language, number, title, active, sheet_music_url) values ($1, 'polish', $2, $3, true, null) on conflict (song_id) do update set language = excluded.language, number = excluded.number, title = excluded.title, active = true, sheet_music_url = null, updated_at = now()", ["demo-pl-101", "101", "Demo Polish Song"]);
    await client.query("insert into app_users (id, display_name, person_id, active) values ($1, $2, $3, true) on conflict (id) do update set display_name = excluded.display_name, person_id = excluded.person_id, active = true", ["demo-priest-user", "Demo Priest User", "demo-priest"]);
    await client.query("insert into app_users (id, display_name, person_id, active) values ($1, $2, $3, true) on conflict (id) do update set display_name = excluded.display_name, person_id = excluded.person_id, active = true", ["demo-organist-user", "Demo Organist User", "demo-organist"]);
    await client.query("insert into app_users (id, display_name, person_id, active) values ($1, $2, null, true) on conflict (id) do update set display_name = excluded.display_name, person_id = null, active = true", ["demo-admin-user", "Demo Admin User"]);
    await client.query("insert into app_users (id, display_name, person_id, active) values ($1, $2, null, true) on conflict (id) do update set display_name = excluded.display_name, person_id = null, active = true", ["demo-member-user", "Demo Congregation User"]);
    await client.query("insert into app_user_roles (user_id, role) values ($1, 'priest'), ($2, 'organist'), ($3, 'admin'), ($4, 'congregation_member') on conflict do nothing", ["demo-priest-user", "demo-organist-user", "demo-admin-user", "demo-member-user"]);
    await client.query("insert into preference_profiles (id, user_id, category) values ($1, $2, 'priest'), ($3, $4, 'organist'), ($5, $6, 'congregation_member') on conflict (user_id) do update set id = excluded.id, category = excluded.category", ["pref-priest", "demo-priest-user", "pref-organist", "demo-organist-user", "pref-member", "demo-member-user"]);
    await client.query("insert into melody_equivalence_classes (id, label, synthetic) values ($1, $2, true) on conflict (id) do update set label = excluded.label, synthetic = true", ["synthetic-melody-a", "Synthetic melody A"]);
    await client.query("insert into song_melody_equivalence (song_id, class_id) values ($1, $2) on conflict (song_id) do update set class_id = excluded.class_id", ["demo-cz-101", "synthetic-melody-a"]);
    await client.query("insert into song_melody_equivalence (song_id, class_id) values ($1, $2) on conflict (song_id) do update set class_id = excluded.class_id", ["demo-pl-101", "synthetic-melody-a"]);
    await client.query("insert into antiphon_mappings (id, antiphon_key, song_id, synthetic) values ($1, $2, $3, true) on conflict (id) do update set antiphon_key = excluded.antiphon_key, song_id = excluded.song_id, synthetic = true", ["synthetic-antiphon-entry", "synthetic-entry", "demo-cz-101"]);
    await client.query("insert into liturgical_season_mappings (id, season_key, song_id, synthetic) values ($1, $2, $3, true) on conflict (id) do update set season_key = excluded.season_key, song_id = excluded.song_id, synthetic = true", ["synthetic-season-advent", "synthetic-advent", "demo-pl-101"]);
    await client.query("insert into song_preferences (profile_id, song_id, score) values ($1, $2, 3) on conflict (profile_id, song_id) do update set score = excluded.score", ["pref-priest", "demo-cz-101"]);
    await client.query("insert into song_preferences (profile_id, song_id, score) values ($1, $2, 2) on conflict (profile_id, song_id) do update set score = excluded.score", ["pref-organist", "demo-cz-101"]);
    await client.query("insert into song_preferences (profile_id, song_id, score) values ($1, $2, 1) on conflict (profile_id, song_id) do update set score = excluded.score", ["pref-member", "demo-cz-101"]);
    await client.query("insert into organist_repertoire (organist_person_id, song_id) values ($1, $2) on conflict do nothing", ["demo-organist", "demo-cz-101"]);
    await client.query("commit");
  } catch (error) {
    await client.query("rollback");
    throw error;
  } finally {
    client.release();
  }
}

export { canManageKnowledge, canManageRepertoire, getCandidateSignal, getPreferenceShade, preferenceScoreLimit, validateOwnPreferenceScore } from "./interaction-contracts";
import type { ServiceLanguage } from "../planning-lifecycle";
export function languagesForServiceShim(language: ServiceLanguage): ("czech" | "polish")[] { return language === "mixed" ? ["czech", "polish"] : [language]; }

import { InMemoryInteractionRepository, type ActorIdentity, type AppUser, type CandidateHydrationInput, type CandidateQueryInput, type CandidateQueryResult, type KnowledgeMapping, type MelodyClass, type MelodyNonRepetitionConfig, type PreferenceProfile, type ReferenceOwnPreference, type ReferencePreferenceAggregate, type SongPreference } from "./interaction-contracts";
import { canManageKnowledge, canManageRepertoire, getCandidateSignal, getPreferenceShade, languagesForServiceShim, preferenceScoreLimit, validateOwnPreferenceScore } from "./interaction-service-utils";
import type { CatalogSong, CatalogRepository } from "./catalog";

export interface InteractionRepository {
  listUsers(): Promise<AppUser[]>;
  listProfiles(): Promise<PreferenceProfile[]>;
  listPreferences(): Promise<SongPreference[]>;
  upsertPreference(preference: SongPreference): Promise<SongPreference>;
  referenceSongExists?(referenceSongId: string): Promise<boolean>;
  getReferenceOwnPreference?(profileId: string, referenceSongId: string): Promise<number | undefined>;
  getReferencePreferenceAggregate?(referenceSongId: string): Promise<number>;
  upsertReferenceOwnPreference?(profileId: string, referenceSongId: string, score: number): Promise<number>;
  listRepertoire(organistPersonId: string): Promise<string[]>;
  setRepertoire(organistPersonId: string, songId: string, active: boolean): Promise<void>;
  listMelodyClasses(): Promise<MelodyClass[]>;
  listKnowledge(): Promise<{ antiphons: KnowledgeMapping[]; seasons: KnowledgeMapping[]; melodyWindow: MelodyNonRepetitionConfig; melodyClasses: MelodyClass[] }>;
  setMelodyWindow(config: MelodyNonRepetitionConfig): Promise<MelodyNonRepetitionConfig>;
}

export type InteractionResult<T> = { success: true; value: T } | { success: false; error: { code: "permissionDenied" | "notFound" | "invalidInput"; message: string } };

export class InteractionService {
  constructor(private readonly repo: InteractionRepository, private readonly catalog: Pick<CatalogRepository, "listSongs">) {}
  async resolveActor(userId: string, requestedRole?: ActorIdentity["role"]): Promise<InteractionResult<ActorIdentity>> { const users = await this.repo.listUsers(); const user = users.find((u) => u.id === userId && u.active); if (!user) return fail("notFound", "Actor was not found."); const role = requestedRole && user.roles.includes(requestedRole) ? requestedRole : user.roles[0]; if (!role) return fail("permissionDenied", "Actor has no active role."); return ok({ userId: user.id, displayName: user.displayName, role, ...(user.personId ? { personId: user.personId } : {}) }); }
  async saveOwnPreference(actor: ActorIdentity, songId: string, score: number): Promise<InteractionResult<SongPreference>> { const verified = await this.verifyActor(actor); if (!verified.success) return verified; actor = verified.value; const profile = (await this.repo.listProfiles()).find((p) => p.userId === actor.userId); if (!profile) return fail("notFound", "Preference profile was not found."); if (!validateOwnPreferenceScore(profile.category, score)) return fail("invalidInput", `Preference score must be between 0 and ${preferenceScoreLimit(profile.category)}.`); return ok(await this.repo.upsertPreference({ profileId: profile.id, songId, score })); }
  async getReferenceOwnPreference(actor: ActorIdentity, referenceSongId: string): Promise<InteractionResult<ReferenceOwnPreference>> {
    const context = await this.resolveReferencePreferenceContext(actor, referenceSongId); if (!context.success) return context;
    return ok({ referenceSongId, category: context.value.profile.category, score: (await this.repo.getReferenceOwnPreference!(context.value.profile.id, referenceSongId)) ?? null, limit: preferenceScoreLimit(context.value.profile.category) });
  }
  async saveReferenceOwnPreference(actor: ActorIdentity, referenceSongId: string, score: number): Promise<InteractionResult<ReferenceOwnPreference>> {
    const context = await this.resolveReferencePreferenceContext(actor, referenceSongId); if (!context.success) return context;
    const { profile } = context.value; if (!validateOwnPreferenceScore(profile.category, score)) return fail("invalidInput", `Preference score must be an integer between 0 and ${preferenceScoreLimit(profile.category)}.`);
    return ok({ referenceSongId, category: profile.category, score: await this.repo.upsertReferenceOwnPreference!(profile.id, referenceSongId, score), limit: preferenceScoreLimit(profile.category) });
  }
  async getReferencePreferenceAggregate(actor: ActorIdentity, referenceSongId: string): Promise<InteractionResult<ReferencePreferenceAggregate>> {
    const verified = await this.verifyActor(actor); if (!verified.success) return verified;
    if (!this.repo.referenceSongExists || !this.repo.getReferencePreferenceAggregate || !await this.repo.referenceSongExists(referenceSongId)) return fail("notFound", "Reference catalog record was not found.");
    return ok({ referenceSongId, aggregateScore: await this.repo.getReferencePreferenceAggregate(referenceSongId) });
  }
  async setRepertoire(actor: ActorIdentity, organistPersonId: string, songId: string, active: boolean): Promise<InteractionResult<{ organistPersonId: string; songId: string; active: boolean }>> { const verified = await this.verifyActor(actor); if (!verified.success) return verified; actor = verified.value; if (!canManageRepertoire(actor, organistPersonId)) return fail("permissionDenied", "Actor cannot manage this repertoire."); await this.repo.setRepertoire(organistPersonId, songId, active); return ok({ organistPersonId, songId, active }); }
  async setMelodyWindow(actor: ActorIdentity, config: MelodyNonRepetitionConfig): Promise<InteractionResult<MelodyNonRepetitionConfig>> { const verified = await this.verifyActor(actor); if (!verified.success) return verified; actor = verified.value; if (!canManageKnowledge(actor.role)) return fail("permissionDenied", "Only admin can manage Knowledge."); if (!Number.isInteger(config.months) || config.months < 0 || config.months > 12) return fail("invalidInput", "Melody Protection must be between 0 and 12 calendar months."); return ok(await this.repo.setMelodyWindow({ months: config.months })); }
  async listKnowledge() { return ok(await this.repo.listKnowledge()); }
  private async verifyActor(actor: ActorIdentity): Promise<InteractionResult<ActorIdentity>> {
    const resolved = await this.resolveActor(actor.userId, actor.role);
    if (!resolved.success) return resolved;
    if (resolved.value.role !== actor.role) return fail("permissionDenied", "Actor role is not assigned to the stored user.");
    if ((actor.personId ?? undefined) !== (resolved.value.personId ?? undefined)) return fail("permissionDenied", "Actor person link does not match the stored user.");
    return resolved;
  }
  private async resolveReferencePreferenceContext(actor: ActorIdentity, referenceSongId: string): Promise<InteractionResult<{ actor: ActorIdentity; profile: PreferenceProfile }>> {
    const verified = await this.verifyActor(actor); if (!verified.success) return verified;
    const profile = (await this.repo.listProfiles()).find((item) => item.userId === verified.value.userId);
    if (!profile) return fail("notFound", "Preference profile was not found.");
    if (!this.repo.referenceSongExists || !this.repo.getReferenceOwnPreference || !this.repo.upsertReferenceOwnPreference || !await this.repo.referenceSongExists(referenceSongId)) return fail("notFound", "Reference catalog record was not found.");
    return ok({ actor: verified.value, profile });
  }

  async hydrateCandidates(input: CandidateHydrationInput): Promise<InteractionResult<CandidateQueryResult[]>> {
    const [songs, preferences, repertoire, knowledge] = await Promise.all([this.catalog.listSongs(), this.repo.listPreferences(), input.organistPersonId ? this.repo.listRepertoire(input.organistPersonId) : Promise.resolve([]), this.repo.listKnowledge()]);
    return ok(hydrateCandidatesFromData(songs, preferences, new Set(repertoire), knowledge, input));
  }

  async queryCandidates(input: CandidateQueryInput): Promise<InteractionResult<CandidateQueryResult[]>> { const [songs, preferences, repertoire, knowledge] = await Promise.all([this.catalog.listSongs(), this.repo.listPreferences(), input.organistPersonId ? this.repo.listRepertoire(input.organistPersonId) : Promise.resolve([]), this.repo.listKnowledge()]); return ok(queryCandidatesFromData(songs, preferences, new Set(repertoire), knowledge, input)); }
}

export class InMemoryInteractionServiceRepository implements InteractionRepository {
  constructor(private readonly repo: InMemoryInteractionRepository) {}
  async listUsers() { return this.repo.listUsers(); }
  async listProfiles() { return this.repo.profiles.map((profile) => ({ ...profile })); }
  async listPreferences() { return this.repo.listPreferences(); }
  async upsertPreference(preference: SongPreference) { const actor = this.repo.resolveActor(preference.profileId.includes("organist") ? "demo-organist-user" : preference.profileId.includes("member") ? "demo-member-user" : "demo-priest-user")!; return this.repo.saveOwnPreference(actor, preference.songId, preference.score) ?? preference; }
  async referenceSongExists() { return false; }
  async getReferenceOwnPreference() { return undefined; }
  async getReferencePreferenceAggregate() { return 0; }
  async upsertReferenceOwnPreference(_profileId: string, _referenceSongId: string, score: number) { return score; }
  async listRepertoire(organistPersonId: string) { return this.repo.listRepertoire(organistPersonId); }
  async setRepertoire(organistPersonId: string, songId: string, active: boolean) { const actor = this.repo.resolveActor("demo-admin-user")!; this.repo.setRepertoire(actor, organistPersonId, songId, active); }
  async listMelodyClasses() { return this.repo.listMelodyClasses(); }
  async listKnowledge() { return this.repo.listKnowledge(); }
  async setMelodyWindow(config: MelodyNonRepetitionConfig) { const actor = this.repo.resolveActor("demo-admin-user")!; this.repo.setMelodyWindow(actor, config); return this.repo.getMelodyWindow(); }
}

export function queryCandidatesFromData(songs: CatalogSong[], preferences: SongPreference[], repertoire: Set<string>, knowledge: { antiphons: KnowledgeMapping[]; seasons: KnowledgeMapping[]; melodyClasses: MelodyClass[]; melodyWindow?: MelodyNonRepetitionConfig }, input: CandidateQueryInput): CandidateQueryResult[] {
  const languageSet = new Set(languagesForServiceShim(input.serviceLanguage));
  const window = knowledge.melodyWindow ?? { months: 2 };
  const recentClassIds = getRecentMelodyClassIds(knowledge.melodyClasses, input, window);
  const queryText = input.queryText?.trim().toLocaleLowerCase() ?? "";
  const threshold = input.preferenceThreshold ?? 0;
  const songsById = new Map(songs.map((song) => [song.songId, song]));
  const candidates: CandidateQueryResult[] = [];

  for (const song of songs) {
    if (!song.active || !languageSet.has(song.language)) continue;
    const melody = knowledge.melodyClasses.find((item) => item.songIds.includes(song.songId));
    const classId = melody?.id ?? `song:${song.songId}`;
    if (melody && recentClassIds.has(melody.id)) continue;
    const allClassSongIds = melody?.songIds ?? [song.songId];
    if (input.organistPersonId && !allClassSongIds.some((songId) => repertoire.has(songId))) continue;

    const aggregatePreferenceScore = preferences.filter((preference) => preference.songId === song.songId).reduce((sum, preference) => sum + preference.score, 0);
    if (aggregatePreferenceScore < threshold) continue;
    if (queryText && !song.number.toLocaleLowerCase().includes(queryText) && !song.title.toLocaleLowerCase().includes(queryText)) continue;

    const antiphonMatch = Boolean(input.antiphonKey && knowledge.antiphons.some((mapping) => mapping.key === input.antiphonKey && mapping.songId === song.songId));
    const seasonMatch = Boolean(input.liturgicalSeasonKey && knowledge.seasons.some((mapping) => mapping.key === input.liturgicalSeasonKey && mapping.songId === song.songId));
    const signal = getCandidateSignal({ antiphonMatch, seasonMatch });
    const melodyMembers = buildMemoryMelodyMembers(song, allClassSongIds, songsById, preferences, repertoire);
    const equivalentNumbers = melodyMembers
      .filter((member) => member.songId !== song.songId)
      .map((member) => ({ songId: member.songId, number: member.number, repertoire: member.repertoire }));

    candidates.push({
      songId: song.songId,
      language: song.language,
      number: song.number,
      title: song.title,
      equivalentNumbers,
      melodyClassId: classId,
      melodyMembers,
      aggregatePreferenceScore,
      antiphonMatch,
      seasonMatch,
      signal,
      preferenceShade: getPreferenceShade(aggregatePreferenceScore),
      repertoire: repertoire.has(song.songId),
      availability: availabilityForClass(knowledge.melodyClasses, classId, input.candidateUsages ?? []),
      suppressedByMelodyWindow: false,
      ...(song.sheetMusicUrl ? { sheetMusicUrl: song.sheetMusicUrl } : {}),
      orderKey: memoryConcreteOrderKey(song),
    });
  }
  return candidates.sort((left, right) => left.orderKey.localeCompare(right.orderKey));
}

function memoryConcreteOrderKey(song: CatalogSong): string {
  const match = song.number.match(/^(\d+)(?:\/(\d+))?$/);
  const numberKey = match
    ? `${String(Number(match[1])).padStart(8, "0")}:${String(Number(match[2] ?? 0)).padStart(3, "0")}`
    : song.number;
  return `${song.language === "czech" ? 0 : 1}:${numberKey}:${song.songId}`;
}
function buildMemoryMelodyMembers(primary: CatalogSong, classSongIds: string[], songsById: Map<string, CatalogSong>, preferences: SongPreference[], repertoire: Set<string>) {
  const members = classSongIds
    .map((songId) => songsById.get(songId))
    .filter((song): song is CatalogSong => Boolean(song?.active));
  const ordered = [primary, ...members.filter((song) => song.songId !== primary.songId).sort((left, right) => `${left.language}:${left.number}:${left.songId}`.localeCompare(`${right.language}:${right.number}:${right.songId}`))];
  return ordered.map((song) => ({
    songId: song.songId,
    language: song.language,
    number: song.number,
    title: song.title,
    repertoire: repertoire.has(song.songId),
    aggregatePreferenceScore: preferences.filter((preference) => preference.songId === song.songId).reduce((sum, preference) => sum + preference.score, 0),
    ...(song.sheetMusicUrl ? { sheetMusicUrl: song.sheetMusicUrl } : {}),
  }));
}

function ok<T>(value: T): InteractionResult<T> { return { success: true, value }; }
function fail<T>(code: "permissionDenied" | "notFound" | "invalidInput", message: string): InteractionResult<T> { return { success: false, error: { code, message } }; }

function getRecentMelodyClassIds(classes: MelodyClass[], input: CandidateQueryInput, window: MelodyNonRepetitionConfig): Set<string> {
  const ids = new Set<string>();
  const target = Date.parse(`${input.serviceDate}T00:00:00Z`);
  const datedUsages = (input.candidateUsages ?? []).filter((usage) => usage.source !== "current" && (!input.currentPlanId || usage.planId !== input.currentPlanId));
  for (const recent of datedUsages) {
    if (!isWithinSymmetricTwoCalendarMonths(target, Date.parse(`${recent.serviceDate}T00:00:00Z`), window.months)) continue;
    for (const melody of classes) if (melody.songIds.includes(recent.songId)) ids.add(melody.id);
  }
  return ids;
}

function isWithinSymmetricTwoCalendarMonths(target: number, usedAt: number, months = 2): boolean { const earlier = addMonthsUtc(target, -months); const later = addMonthsUtc(target, months); return usedAt >= earlier && usedAt <= later; }
function addMonthsUtc(value: number, months: number): number { const date = new Date(value); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, date.getUTCDate()); }

function availabilityForClass(
  classes: MelodyClass[],
  classId: string,
  usages: NonNullable<CandidateQueryInput["candidateUsages"]>,
): CandidateQueryResult["availability"] {
  const rows = usages
    .filter((usage) => usage.source === "current" && classIdForSong(classes, usage.songId) === classId && usage.rowId !== undefined && usage.rowLabel?.trim())
    .map((usage) => ({ rowId: usage.rowId!, label: usage.rowLabel!.trim() }))
    .filter((row, index, all) => all.findIndex((candidate) => candidate.rowId === row.rowId) === index)
    .sort((left, right) => left.rowId - right.rowId || left.label.localeCompare(right.label));
  return rows.length > 0 ? { kind: "occupiedByCurrentRows", rows } : { kind: "available" };
}

function classIdForSong(classes: MelodyClass[], songId: string): string {
  return classes.find((melody) => melody.songIds.includes(songId))?.id ?? `song:${songId}`;
}

export function hydrateCandidatesFromData(songs: CatalogSong[], preferences: SongPreference[], repertoire: Set<string>, knowledge: { antiphons: KnowledgeMapping[]; seasons: KnowledgeMapping[]; melodyClasses: MelodyClass[]; melodyWindow?: MelodyNonRepetitionConfig }, input: CandidateHydrationInput): CandidateQueryResult[] {
  const songsById = new Map(songs.map((song) => [song.songId, song]));
  return input.songs.map((reference) => {
    const storedSong = reference.songId ? songsById.get(reference.songId) : undefined;
    if (!storedSong?.active) return hydrateCandidateFromReference(reference);
    const melody = knowledge.melodyClasses.find((m) => m.songIds.includes(storedSong.songId));
    const classSongIds = melody?.songIds ?? [storedSong.songId];
    const aggregatePreferenceScore = preferences.filter((pref) => pref.songId === storedSong.songId).reduce((sum, pref) => sum + pref.score, 0);
    const antiphonMatch = Boolean(input.antiphonKey && knowledge.antiphons.some((m) => m.key === input.antiphonKey && m.songId === storedSong.songId));
    const seasonMatch = Boolean(input.liturgicalSeasonKey && knowledge.seasons.some((m) => m.key === input.liturgicalSeasonKey && m.songId === storedSong.songId));
    const equivalentNumbers = classSongIds
      .filter((songId) => songId !== storedSong.songId)
      .map((songId) => songsById.get(songId))
      .filter((song): song is CatalogSong => Boolean(song?.active))
      .map((song) => ({ songId: song.songId, number: song.number, repertoire: repertoire.has(song.songId) }))
      .sort((a, b) => `${a.repertoire ? 0 : 1}:${a.number}`.localeCompare(`${b.repertoire ? 0 : 1}:${b.number}`));
    const signal = getCandidateSignal({ antiphonMatch, seasonMatch });
    return {
      songId: storedSong.songId,
      language: storedSong.language,
      number: storedSong.number,
      title: storedSong.title,
      equivalentNumbers,
      melodyClassId: melody?.id ?? `song:${storedSong.songId}`,
      melodyMembers: buildMemoryMelodyMembers(storedSong, classSongIds, songsById, preferences, repertoire),
      aggregatePreferenceScore,
      antiphonMatch,
      seasonMatch,
      signal,
      preferenceShade: getPreferenceShade(aggregatePreferenceScore),
      repertoire: repertoire.has(storedSong.songId),
      availability: { kind: "available" },
      suppressedByMelodyWindow: false,
      ...(storedSong.sheetMusicUrl ? { sheetMusicUrl: storedSong.sheetMusicUrl } : {}),
      orderKey: `hydrated:${storedSong.language}:${storedSong.number}:${storedSong.songId}`,
    };
  });
}

function hydrateCandidateFromReference(song: { songId?: string; language: CatalogSong["language"]; number: string; title?: string }): CandidateQueryResult { const songId = song.songId ?? `historical:${song.language}:${song.number}`; return { songId, language: song.language, number: song.number, title: song.title ?? "Untitled snapshot", equivalentNumbers: [], aggregatePreferenceScore: 0, antiphonMatch: false, seasonMatch: false, signal: "none", preferenceShade: "none", repertoire: false, availability: { kind: "available" }, suppressedByMelodyWindow: false, orderKey: `rehydrated:${song.language}:${song.number}:${songId}` }; }

import type { Pool } from "pg";
import type { ActorIdentity, AppUser } from "./interaction-contracts";
import type { PlanningRole } from "../planning-lifecycle";

export type LocalActorContext = { userId: string; role?: PlanningRole };
const ROLE_ORDER: PlanningRole[] = ["priest", "organist", "admin", "congregationMember"];

export class LocalActorError extends Error {
  constructor(public readonly code: "invalidInput" | "permissionDenied", message: string) {
    super(message);
  }
}

/** DB-runtime identity boundary for the deliberately local, non-authenticated user simulator. */
export class PostgresLocalActorResolver {
  constructor(private readonly pool: Pick<Pool, "query">) {}

  async listActiveUsers(): Promise<AppUser[]> {
    const { rows } = await this.pool.query(`
      select u.id, u.display_name, u.person_id, u.active,
        coalesce(array_agg(r.role order by r.role) filter (where r.role is not null), '{}') roles
      from app_users u left join app_user_roles r on r.user_id = u.id
      where u.active = true group by u.id order by u.display_name, u.id
    `);
    return rows.map(mapUser).filter((user) => user.roles.length > 0);
  }

  async resolve(context: LocalActorContext): Promise<ActorIdentity> {
    const { userId, role: requestedRole } = context;
    const { rows } = await this.pool.query(`
      select u.id, u.display_name, u.person_id, u.active,
        coalesce(array_agg(r.role order by r.role) filter (where r.role is not null), '{}') roles
      from app_users u left join app_user_roles r on r.user_id = u.id
      where u.id = $1 group by u.id
    `, [userId]);
    if (!rows[0]) throw new LocalActorError("permissionDenied", "The selected local actor does not exist.");
    const user = mapUser(rows[0]);
    if (!user.active) throw new LocalActorError("permissionDenied", "The selected local actor is inactive.");
    if (user.roles.length === 0) throw new LocalActorError("permissionDenied", "The selected local actor has no assigned role.");
    if (requestedRole && !user.roles.includes(requestedRole)) throw new LocalActorError("permissionDenied", "The requested role is not assigned to the selected local actor.");
    // The fixed competency order is the deterministic default when the envelope omits role.
    const role = requestedRole ?? ROLE_ORDER.find((candidate) => user.roles.includes(candidate))!;
    return { userId: user.id, displayName: user.displayName, role, ...(user.personId ? { personId: user.personId } : {}) };
  }
}

export function parseLocalActorContext(value: unknown): LocalActorContext {
  if (typeof value !== "object" || value === null || Array.isArray(value)) throw new LocalActorError("invalidInput", "Local actor context is required.");
  const { userId, role } = value as Record<string, unknown>;
  if (typeof userId !== "string" || !userId.trim()) throw new LocalActorError("invalidInput", "Local actor userId must be a non-empty string.");
  if (role !== undefined && !ROLE_ORDER.includes(role as PlanningRole)) throw new LocalActorError("invalidInput", "Local actor role is malformed.");
  return { userId: userId.trim(), ...(role ? { role: role as PlanningRole } : {}) };
}

function mapUser(row: Record<string, unknown>): AppUser {
  return { id: String(row.id), displayName: String(row.display_name), ...(row.person_id ? { personId: String(row.person_id) } : {}), active: Boolean(row.active), roles: normalizeRoles(row.roles).sort((a, b) => ROLE_ORDER.indexOf(a) - ROLE_ORDER.indexOf(b)) };
}
function normalizeRoles(value: unknown): PlanningRole[] {
  const roles = Array.isArray(value) ? value.map(String) : typeof value === "string" ? value.replace(/[{}]/g, "").split(",").filter(Boolean) : [];
  return roles.map((role) => role === "congregation_member" ? "congregationMember" : role as PlanningRole);
}

export type NonRepetitionPlanStatus = "working" | "final";

export type NonRepetitionPlanMelodyUsage = {
  planId: string;
  status: NonRepetitionPlanStatus;
  serviceDate: string;
  melodyClassId: string;
};

export type NonRepetitionPlanConflict = {
  melodyClassId: string;
  left: {
    planId: string;
    status: NonRepetitionPlanStatus;
    serviceDate: string;
  };
  right: {
    planId: string;
    status: NonRepetitionPlanStatus;
    serviceDate: string;
  };
};

export type MelodyWindowValue = { months: number };

export type MelodyWindowFailure = {
  success: false;
  error: {
    code: "permissionDenied" | "invalidInput" | "conflict";
    message: string;
    conflicts?: NonRepetitionPlanConflict[];
  };
};

export type MelodyWindowResult =
  | { success: true; value: MelodyWindowValue }
  | MelodyWindowFailure;

export type NonRepetitionPlanLike = {
  id: string;
  status: NonRepetitionPlanStatus;
  serviceContext: { serviceDate: string };
  rows: { song?: { songId?: string } }[];
};

export function validateMelodyWindowMonths(months: unknown): months is number {
  return typeof months === "number" && Number.isFinite(months) && Number.isInteger(months) && months >= 0 && months <= 12;
}

export function buildNonRepetitionPlanMelodyUsages(
  plans: NonRepetitionPlanLike[],
  classBySongId: ReadonlyMap<string, string>,
): NonRepetitionPlanMelodyUsage[] {
  const usages: NonRepetitionPlanMelodyUsage[] = [];
  for (const plan of plans) {
    const classes = new Set<string>();
    for (const row of plan.rows) {
      const songId = row.song?.songId;
      const melodyClassId = songId ? classBySongId.get(songId) : undefined;
      if (melodyClassId) classes.add(melodyClassId);
    }
    for (const melodyClassId of [...classes].sort()) {
      usages.push({
        planId: plan.id,
        status: plan.status,
        serviceDate: plan.serviceContext.serviceDate,
        melodyClassId,
      });
    }
  }
  return usages.sort(compareUsage);
}

export function findNonRepetitionPlanConflicts(
  usages: NonRepetitionPlanMelodyUsage[],
  months: number,
): NonRepetitionPlanConflict[] {
  if (!validateMelodyWindowMonths(months)) return [];

  const unique = new Map<string, NonRepetitionPlanMelodyUsage>();
  for (const usage of usages) {
    if (!usage.planId || !usage.melodyClassId || !isIsoDate(usage.serviceDate)) continue;
    unique.set(`${usage.planId}\u0000${usage.melodyClassId}`, { ...usage });
  }

  const byClass = new Map<string, NonRepetitionPlanMelodyUsage[]>();
  for (const usage of unique.values()) {
    byClass.set(usage.melodyClassId, [...(byClass.get(usage.melodyClassId) ?? []), usage]);
  }

  const conflicts: NonRepetitionPlanConflict[] = [];
  for (const melodyClassId of [...byClass.keys()].sort()) {
    const classUsages = (byClass.get(melodyClassId) ?? []).sort(compareUsage);
    for (let leftIndex = 0; leftIndex < classUsages.length; leftIndex += 1) {
      const left = classUsages[leftIndex];
      for (let rightIndex = leftIndex + 1; rightIndex < classUsages.length; rightIndex += 1) {
        const right = classUsages[rightIndex];
        if (left.planId === right.planId) continue;
        if (!isWithinCalendarMonths(left.serviceDate, right.serviceDate, months)) continue;
        conflicts.push({
          melodyClassId,
          left: planSummary(left),
          right: planSummary(right),
        });
      }
    }
  }

  return conflicts.sort(compareConflict);
}

export function melodyWindowConflictMessage(conflicts: NonRepetitionPlanConflict[], months: number): string {
  if (conflicts.length === 0) return "Melody non-repetition period conflicts with saved planning sets.";
  const first = conflicts[0];
  const count = conflicts.length === 1 ? "1 conflict" : `${conflicts.length} conflicts`;
  return `Cannot change melody non-repetition period to ${months} calendar month${months === 1 ? "" : "s"}: ${count}. ${formatPlan(first.left)} and ${formatPlan(first.right)} share melody class ${first.melodyClassId}. Delete one or more blocking saved sets and retry.`;
}

export function isWithinCalendarMonths(leftDate: string, rightDate: string, months: number): boolean {
  if (!validateMelodyWindowMonths(months) || !isIsoDate(leftDate) || !isIsoDate(rightDate)) return false;
  const left = Date.parse(`${leftDate}T00:00:00Z`);
  const right = Date.parse(`${rightDate}T00:00:00Z`);
  return right >= addMonthsUtc(left, -months) && right <= addMonthsUtc(left, months);
}

function addMonthsUtc(value: number, months: number): number {
  const date = new Date(value);
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, date.getUTCDate());
}

function planSummary(usage: NonRepetitionPlanMelodyUsage): NonRepetitionPlanConflict["left"] {
  return { planId: usage.planId, status: usage.status, serviceDate: usage.serviceDate };
}

function formatPlan(plan: NonRepetitionPlanConflict["left"]): string {
  return `${plan.status} set ${plan.planId} (${plan.serviceDate})`;
}

function compareUsage(left: NonRepetitionPlanMelodyUsage, right: NonRepetitionPlanMelodyUsage): number {
  return `${left.serviceDate}:${left.planId}:${left.status}:${left.melodyClassId}`.localeCompare(`${right.serviceDate}:${right.planId}:${right.status}:${right.melodyClassId}`);
}

function compareConflict(left: NonRepetitionPlanConflict, right: NonRepetitionPlanConflict): number {
  return `${left.left.serviceDate}:${left.left.planId}:${left.right.serviceDate}:${left.right.planId}:${left.melodyClassId}`.localeCompare(`${right.left.serviceDate}:${right.left.planId}:${right.right.serviceDate}:${right.right.planId}:${right.melodyClassId}`);
}

function isIsoDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = Date.parse(`${value}T00:00:00Z`);
  return Number.isFinite(parsed) && new Date(parsed).toISOString().slice(0, 10) === value;
}
